(:
-----סדר הקרבנות
סדר הקרבנות
:)

(:
פרשת הכיור
:)
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר: וְעָשִׂיתָ כִּיּוֹר נְחֹשֶׁת וְכַנּוֹ נְחֹשֶׁת לְרKחְצָה, וְנָתַתָּ אֹתוֹ בֵּין אֹהֶל מוֹעֵד וּבֵין הַמִּזְבֵּחַ, וְנָתַתָּ שָׁמָּה מָיִם; וְרָחֲצוּ אַהֲרֹן וּבָנָיו מִמֶּנּוּ אֶת יְדֵיהֶם וְאֶת רַגְלֵיהֶם; בְּבֹאָם אֶל אֹהֶל מוֹעֵד יִרְחֲצוּ מַיִם וְלֹא יָמֻתוּ, אוֹ בְגִשְׁתָּם אֶל הַמִּזְבֵּחַ לְשָׁרֵת, לְהַקְטִיר אִשֶּׁה לַי~הוה; וְרָחֲצוּ יְדֵיהֶם וְרַגְלֵיהֶם וְלֹא יָמֻתוּ, וְהָיְתָה לָהֶם חKק עוֹלָם, לוֹ וּלְזַרְעוֹ לְדֹרֹתָם;


(:
פרשת תרומת הדשן
:)
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר, זֹאת תּוֹרַת הָעֹלָה, הִיא הָעֹלָה עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כּKל הַלַּיְלָה עַד הַבֹּקֶר, וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּוֹ; וְלָבַשׁ הַכֹּהֵן מִדּוֹ בַד וּמִכְנְסֵי בַד יִלְבַּשׁ עַל בְּשָׂרוֹ, וְהֵרִים אֶת הַדֶּשֶׁן אֲשֶׁר תֹּאכַל הָאֵשׁ, אֶת הָעֹלָה עַל הַמִּזְבֵּחַ, וְשָׂמוֹ אֵצֶל הַמִּזְבֵּחַ; וּפָשַׁט אֶת בְּגָדָיו, וְלָבַשׁ בְּגָדִים אֲחֵרִים, וְהוֹצִיא אֶת הַדֶּשֶׁן אֶל מִחוּץ לַמַּחֲנֶה אֶל מָקוֹם טָהור; וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ לֹא תִכְבֶּה, וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר, וְעָרַךְ עָלֶיהָ הָעֹלָה וְהִקְטִיר עָלֶיהָ חֶלְבֵי הַשְּׁלָמִים; אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה;


(:
פרשת התמיד
:)
יְהִי רָצוֹן מִלְּפָנֶיךָ י~הוה אֱ~לֹהֵינוּ וֵא~לֹהֵי אֲבוֹתֵינוּ, שֶׁתְּרַחֵם עָלֵינוּ וְתִמְחֹל לָנוּ עַל כּKל חַטֹּאתֵינוּ וּתְכַפֶּר לָנוּ עַל כּKל עֲוׂנוֹתֵינוּ וְתִסְלַח לָנוּ עַל כּKל פְּשָׁעֵינוּ, וְתִבְנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְיָמֵינוּ, וְנַקְרִיב לְפָנֶיךָ קKרְבַּן הַתָּמִיד שֶׁיְּכַפֵּר בַּעֲדֵנוּ, כְּמוֹ שֶׁכָּתַבְתָּ עָלֵינוּ בְּתוֹרָתֶךָ עַל יְדֵי מֹשֶׁה עַבְדֶּךָ מִפִּי כְבוֹדֶךָ, כָּאָמוּר:

וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; צַו אֶת בְּנֵי יִשרָאֵל וְאָמַרְתָּ אֲלֵהֶם, אֶת קKרְבָּנִי לַחְמִי לְאִשַּׁי, רֵיחַ נִיחֹחִי, תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ; וְאָמַרְתָּ לָהֶם, זֶה הָאִשֶּׁה אֲשֶׁר תַּקְרִיבוּ לַי~הוה, כְּבָשִׂים בְּנֵי שָׁנָה תְמִימִים, שְׁנַיִם לַיּוֹם עֹלָה תָמִיד; אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַבֹּקֶר, וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם; וַעֲשִׂירִית הָאֵיפָה סֹלֶת לְמִנְחָה, בְּלוּלָה בְּשֶׁמֶן כָּתִית רְבִיעִת הַהִין; עֹלַת תָּמִיד, הָעֲשֻׂיָה בְּהַר סִינַי, לְרֵיחַ נִיחֹחַ אִשֶּׁה לַי~הוה; וְנִסְכּוֹ רְבִיעִת הַהִין לַכֶּבֶשׂ הָאֶחָד, בַּקֹּדֶשׁ הַסֵּךְ נֶסֶךְ שֵׁכָר לַי~הוה; וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם, כְּמִנְחַת הַבֹּקֶר וּכְנִסְכּוֹ תַּעֲשֶׂה, אִשֵּׁה רֵיחַ נִיחֹחַ לַי~הוה;

וְשָׁחַט אֹתוֹ עַל יֶרֶךְ הַמִּזְבֵּחַ צָפֹנָה לִפְנֵי י~הוה, וְזָרְקוּ בְּנֵי אַהֲרֹן הַכֹּהֲנִים אֶת דָּמוֹ עַל הַמִּזְבֵּחַ סָבִיב;

יְהִי רָצוֹן מִלְּפָנֶיךָ י~הוה אֱ~לֹהֵינוּ וֵא~לֹהֵי אֲבוֹתֵינוּ, שֶׁתְּהֵא אֲמִירָה זוֹ חֲשׁוּבָה וּמְקֻבֶּלֶת וּמְרֻצָּה לְפָנֶיךָ כְּאִלּוּ הִקְרַבְנוּ קKרְבַּן הַתָּמִיד בְּמוֹעֲדוֹ וּבִמְקוֹמוֹ וּכְהִלְכָתוֹ;


(:
פרשת הקטורת
:)
אַתָּה הוּא י~הוה אֱ~לֹהֵינוּ שֶׁהִקְטִירוּ אֲבוֹתֵינוּ לְפָנֶיךָ אֶת קְטֹרֶת הַסַּמִּים בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ הָיָה קַיָּם, כַּאֲשֶׁר צִוִּיתָ אוֹתָם עַל יַד מֹשֶׁה נְבִיאֶךָ, כַּכָּתוּב בְּתוֹרָתֶךָ: וַיֹּאמֶר י~הוה אֶל מֹשֶׁה, קַח לְךָ סַמִּים נָטָף וּשְׁחֵלֶת וְחֶלְבְּנָה סַמִּים וּלְבֹנָה זַכָּה בַּד בְּבַד יִהְיֶה; וְעָשִׂיתָ אֹתָהּ קְטֹרֶת, רֹקַח מַעֲשֶׂה רוֹקֵחַ, מְמֻלָּח טָהוֹר קֹדֶשׁ; וְשָׁחַקְתָּ מִמֶּנָּה הָדֵק, וְנָתַתָּה מִמֶּנָּה לִפְנֵי הָעֵדֻת בְּאֹהֶל מוֹעֵד אֲשֶׁר אִוָּעֵד לְךָ שָׁמָּה, קֹדֶשׁ קָדָשִׁים תִּהְיֶה לָכֶם;

וְנֶאֱמַר: וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים, בַּבֹּקֶר בַּבֹּקֶר בְּהֵיטִיבוֹ אֶת הַנֵּרוֹת יַקְטִירֶנָּה; וּבְהַעֲלֹת אַהֲרֹן אֶת הַנֵּרֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה, קְטֹרֶת תָּמִיד לִפְנֵי י~הוה לְדֹרֹתֵיכֶם;

תָּנוּ רַבָּנָן: פִּטּוּם הַקְּטֹרֶת כֵּיצַד? שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וּשְׁמוֹנָה מָנִים הָיוּ בָהּ. שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה כְּמִנְיַן יְמוֹת הַחַמָּה, מָנֶה לְכKל יוֹם, פְּרַס בְּשַׁחֲרִית וּפְרַס בֵּין הָעַרְבָּיִם. וּשְׁלֹשָׁה מָנִים יְתֵרִים שֶׁמֵּהֶם מַכְנִיס כֹּהֵן גָּדוֹל מְלֹא חKפְנָיו בְּיוֹם הַכִּפּוּרִים, וּמַחֲזִירָן לְמַכְתֶּשֶׁת בְּעֶרֶב יוֹם הַכִּפּוּרִים, וְשׁוֹחֲקָן יָפֶה יָפֶה כְּדֵי שֶׁתְּהֵא דַקָּה מִן הַדַּקָּה. וְאַחַד עָשָׂר סַמָּנִים הָיוּ בָהּ, וְאֵלּוּ הֵן: (א) הַצֳּרִי (ב) וְהַצִּפֹּרֶן, (ג) הַחֶלְבְּנָה (ד) וְהַלְּבוֹנָה מִשְׁקַל שִׁבְעִים שִׁבְעִים מָנֶה, (ה) מֹר (ו) וּקְצִיעָה, (ז) שִׁבֹּלֶת נֵרְדְּ (ח) וְכַרְכֹּם מִשְׁקַל שִׁשָּׁה עָשָׂר שִׁשָּׁה עָשָׂר מָנֶה, (ט) הַקֹּשְׁטְ שְׁנֵים עָשָׂר, (י) קִלּוּפָה שְׁלֹשָׁה, (יא) קִנָּמוֹן תִּשְׁעָה, בֹּרִית כַּרְשִׁינָה תִּשְׁעָה קַבִּין, יֵין קַפְרִיסִין סְאִין תְּלָתָא וְקַבִּין תְּלָתָא, וְאִם לֹא מָצָא יֵין קַפְרִיסִין מֵבִיא חֲמַר חִוַּרְיָן עַתִּיק. מֶלַח סְדוֹמִית רֹבַע מַעֲלֶה עָשָׁן כּKל שֶׁהוּא. רַבִּי נָתָן הַבַּבְלִי אוֹמֵר: אַף כִּפַּת הַיַּרְדֵּן כּKל שֶׁהוּא. וְאִם נָתַן בָּהּ דְּבַשׁ פְּסָלָהּ, וְאִם חִסַּר אַחַת מִכּKל סַמָּנֶיהָ חַיָּב מִיתָה.

רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל אוֹמֵר: הַצֳּרִי אֵינוֹ אֶלָּא שְׂרָף הַנּוֹטֵף מֵעֲצֵי הַקְּטָף. בֹּרִית כַּרְשִׁינָה שֶׁשָּׁפִין בָּהּ אֶת הַצִּפֹּרֶן כְּדֵי שֶׁתְּהֵא נָאָה. יֵין קַפְרִיסִין שֶׁשּׁוֹרִין בּוֹ אֶת הַצִּפֹּרֶן כְּדֵי שֶׁתְּהֵא עַזָּה. וַהֲלֹא מֵי רַגְלַיִם יָפִין לָהּ, אֶלָּא שֶׁאֵין מַכְנִיסִין מֵי רַגְלַיִם בַּמִּקְדָּשׁ מִפְּנֵי הַכָּבוֹד.

תַּנְיָא: רַבִּי נָתָן אוֹמֵר: כְּשֶׁהוּא שׁוֹחֵק אוֹמֵר: הָדֵק הֵיטֵב, הֵיטֵב הָדֵק, מִפְּנֵי שֶׁהַקּוֹל יָפֶה לַבְּשָׂמִים. פִּטְּמָהּ לַחֲצָאִין כְּשֵׁרָה. לִשְׁלִישׁ וְלִרְבִיעַ לֹא שָׁמַעְנוּ. אָמַר רַבִּי יְהוּדָה: זֶה הַכְּלָל: אִם כְּמִדָּתָהּ כְּשֵׁרָה לַחֲצָאִין, וְאִם חִסַּר אַחַת מִכּKל סַמָּנֶיהָ חַיָּב מִיתָה.

