תָּנָא דְבֵי אֵלִיָּהוּ: כּKל הַשּׁוֹנֶה הֲלָכוֹת בְּכKל יוֹם מֻבְטָח לוֹ שֶׁהוּא בֶּן עוֹלָם הַבָּא, שֶׁנֶּאֱמַר: הֲלִיכוֹת עוֹלָם לוֹ; אַל תִּקְרֵי הֲלִיכות אֶלָּא הֲלָכוֹת. אָמַר רַבִּי אֶלְעָזָר אָמַר רַבִּי חֲנִינָא: תַּלְמִידֵי חֲכָמִים מַרְבִּים שָׁלוֹם בָּעוֹלָם, שֶׁנֶּאֱמַר: וְכKל בָּנַיִךְ לִמּוּדֵי י~הוה וְרַב שְׁלוֹם בָּנָיִךְ; אַל תִּקְרֵי בָּנָיִךְ אֶלָּא בּוֹנָיִךְ. שָׁלוֹם רָב לְאֹהֲבֵי תוֹרָתֶךָ, וְאֵין לָמוֹ מִכְשׁוֹל; יְהִי שָׁלוֹם בְּחֵילֵךְ, שַׁלְוָה בְּאַרְמְנוֹתָיִךְ; לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָּא שָׁלוֹם בָּךְ; לְמַעַן בֵּית י~הוה אֱ~לֹהֵינוּ אֲבַקְשָׁה טוֹב לָךְ; י~הוה עֹז לְעַמּוֹ יִתֵּן, י~הוה יְבָרֵךְ אֶת עַמּוֹ בַשָּׁלוֹם;

