וִיהִי נֹעַם אֲ~דֹנָי אֱ~לֹהֵינוּ עָלֵינוּ, וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ, וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנֵהוּ; יֹשֵׁב בְּסֵתֶר עֶלְיוֹן בְּצֵל שַׁ~דַּי יִתְלוֹנָן; אֹמַר לַי~הוה מַחְסִי וּמְצוּדָתִי, אֱ~לֹהַי אֶבְטַח בּוֹ; כִּי הוּא יַצִּילְךָ מִפַּח יָקוּשׁ מִדֶּבֶר הַוּוֹת; בְּאֶבְרָתוֹ יָסֶךְ לָךְ וְתַחַת כְּנָפָיו תֶּחְסֶה, צִנָּה וְסֹחֵרָה אֲמִתּוֹ; לֹא תִירָא מִפַּחַד לָיְלָה, מֵחֵץ יָעוּף יוֹמָם; מִדֶּבֶר בָּאֹפֶל יַהֲלֹךְ, מִקֶּטֶב יָשׁוּד צָהֳרָיִם; יִפֹּל מִצִּדְּךָ אֶלֶף וּרְבָבָה מִימִינֶךָ, אֵלֶיךָ לֹא יִגָּשׁ; רַק בְּעֵינֶיךָ תַבִּיט, וְשִׁלֻּמַת רְשָׁעִים תִּרְאֶה; כִּי אַתָּה י~הוה מַחְסִי, עֶלְיוֹן שַׂמְתָּ מְעוֹנֶךָ; לֹא תְאֻנֶּה אֵלֶיךָ רָעָה, וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךָ; כִּי מַלְאָכָיו יְצַוֶּה לָּךְ, לִשְׁמKרְךָ בְּכKל דְּרָכֶיךָ; עַל כַּפַּיִם יִשָּׂאוּנְךָ, פֶּן תִּגֹּף בָּאֶבֶן רַגְלֶךָ; עַל שַׁחַל וָפֶתֶן תִּדְרֹךְ, תִּרְמֹס כְּפִיר וְתַנִּין; כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ, אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי; יִקְרָאֵנִי וְאֶעֱנֵהוּ, עִמּוֹ אָנֹכִי בְצָרָה, אֲחַלְּצֵהוּ וַאֲכַבְּדֵהוּ; אֹרֶךְ יָמִים אַשְׂבִּיעֵהוּ, וְאַרְאֵהוּ בִּישׁוּעָתִי; אֹרֶךְ יָמִים אַשְׂבִּיעֵהוּ, וְאַרְאֵהוּ בִּישׁוּעָתִי;

י~הוה, מָה רַבּוּ צָרָי, רַבִּים קָמִים עָלָי; רַבִּים אֹמְרִים לְנַפְשִׁי אֵין יְשׁוּעָתָה לּוֹ בֵא~לֹהִים סֶלָה; וְאַתָּה י~הוה מָגֵן בַּעֲדִי, כְּבוֹדִי וּמֵרִים רֹאשִׁי; קוֹלִי אֶל י~הוה אֶקְרָא, וַיַּעֲנֵנִי מֵהַר קKדְשׁוֹ סֶלָה; אֲנִי שָׁכַבְתִּי וָאִישָׁנָה, הֱקִיצוֹתִי כִּי י~הוה יִסְמְכֵנִי; לֹא אִירָא מֵרִבְבוֹת עָם, אֲשֶׁר סָבִיב שָׁתוּ עָלָי; קוּמָה י~הוה הוֹשִׁיעֵנִי אֱ~לֹהַי, כִּי הִכִּיתָ אֶת כּKל אֹיְבַי לֶחִי, שִׁנֵּי רְשָׁעִים שִׁבַּרְתָּ; לַי~הוה הַיְשׁוּעָה עַל עַמְּךָ בִרְכָתֶךָ סֶּלָה;

