לַמְנַצֵּחַ מִזְמוֹר לְדָוִד; הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵ~ל, וּמַעֲשה יָדָיו מַגִּיד הָרָקִיעַ; יוֹם לְיוֹם יַבִּיעַ אֹמֶר, וְלַיְלָה לְלַיְלָה יְחַוֶּה דָּעַת; אֵין אֹמֶר וְאֵין דְּבָרִים, בְּלִי נִשְׁמָע קוֹלָם; בְּכKל הָאָרֶץ יָצָא קַוָּם, וּבִקְצֵה תֵבֵל מִלֵּיהֶם, לַשֶּׁמֶשׁ שָׂם אֹהֶל בָּהֶם; וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ, יָשִׂישׂ כְּגִבּוֹר לָרוּץ אֹרַח; מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ וּתְקוּפָתוֹ עַל קְצוֹתָם, וְאֵין נִסְתָּר מֵחַמָּתוֹ; תּוֹרַת י~הוה תְּמִימָה מְשִׁיבַת נָפֶשׁ, עֵדוּת י~הוה נֶאֱמָנָה מַחְכִּימַת פֶּתִי; פִּקּוּדֵי י~הוה יְשָׁרִים מְשַׂמְּחֵי לֵב, מִצְוַת י~הוה בָּרָה מְאִירַת עֵינָיִם; יִרְאַת י~הוה טְהוֹרָה עומֶדֶת לָעַד, מִשְׁפְּטֵי י~הוה אֱמֶת צָדְקוּ יַחְדָּו; הַנֶחֱמָדִים מִזָּהָב וּמִפָּז רָב, וּמְתוּקִים מִדְּבַשׁ וְנֹפֶת צוּפִים; גַּם עַבְדְּךָ נִזְהָר בָּהֶם, בְּשׁKמְרָם עֵקֶב רָב; שְׁגִיאות מִי יָבִין מִנִּסְתָּרוֹת נַקֵּנִי; גַּם מִזֵּדִים חֲשֹׂךְ עַבְדֶּךָ, אַל יִמְשְׁלוּ בִי אָז אֵיתָם, וְנִקֵּיתִי מִפֶּשַׁע רָב; יִהְיוּ לְרָצון אִמְרֵי פִי וְהֶגְיון לִבִּי לְפָנֶיךָ, י~הוה צוּרִי וְגֹאֲלִי;

