לְדָוִד בְּשַׁנּוֹתו אֶת טַעְמוֹ לִפְנֵי אֲבִימֶלֶךְ, וַיְגָרְשֵׁהוּ וַיֵּלַךְ; אֲבָרְכָה אֶת י~הוה בְּכKל עֵת, תָּמִיד תְּהִלָּתוֹ בְּפִי; בַּי~הוה תִּתְהַלֵּל נַפְשִׁי, יִשְׁמְעוּ עֲנָוִים וְיִשמָחוּ; גַדְּלוּ לַי~הוה אִתִּי, וּנְרוֹמְמָה שְׁמוֹ יַחְדָּו; דָּרַשְׁתִּי אֶת י~הוה וְעָנָנִי, וּמִכּKל מְגוּרוֹתַי הִצִּילָנִי; הִבִּיטוּ אֵלָיו וְנָהָרוּ, וּפְנֵיהֶם אַל יֶחְפָּרוּ; זֶה עָנִי קָרָא וַי~הוה שָׁמֵעַ, וּמִכּKל צָרוֹתָיו הוֹשִׁיעוֹ; חוֹנֶה מַלְאַךְ י~הוה סָבִיב לִירֵאָיו וַיְחַלְּצֵם; טַעֲמוּ וּרְאוּ כִּי טוֹב י~הוה, אַשְׁרֵי הַגֶּבֶר יֶחֱסֶה בּוֹ; יְראוּ אֶת י~הוה קְדוֹשָׁיו, כִּי אֵין מַחְסוֹר לִירֵאָיו; כְּפִירִים רָשׁוּ וְרָעֵבוּ, וְדוֹרְשֵׁי י~הוה לֹא יַחְסְרוּ כKל טוֹב; לְכוּ בָנִים שִׁמְעוּ לִי, יִרְאַת י~הוה אֲלַמֶּדְכֶם; מִי הָאִישׁ הֶחָפֵץ חַיִּים, אֹהֵב יָמִים לִרְאוֹת טוֹב; נְצֹר לְשׁוֹנְךָ מֵרָע, וּשפָתֶיךָ מִדַּבֵּר מִרְמָה; סוּר מֵרָע וַעֲשֵׂה טוֹב, בַּקֵּשׁ שָׁלוֹם וְרKדְפֵהוּ; עֵינֵי י~הוה אֶל צַדִּיקִים, וְאKזְנָיו אֶל שַׁוְעָתָם; פְּנֵי י~הוה בְּעֹשֵׂי רָע, לְהַכְרִית מֵאֶרֶץ זִכְרָם; צָעֲקוּ וַי~הוה שָׁמֵעַ, וּמִכּKל צָרוֹתָם הִצִּילָם; קָרוֹב י~הוה לְנִשְׁבְּרֵי לֵב, וְאֶת דַּכְּאֵי רוּחַ יוֹשִׁיעַ; רַבּוֹת רָעוֹת צַדִּיק, וּמִכֻּלָּם יַצִּילֶנּוּ י~הוה; שֹׁמֵר כּKל עַצְמוֹתָיו, אַחַת מֵהֵנָּה לֹא נִשְׁבָּרָה; תְּמוֹתֵת רָשָׁע רָעָה, וְשֹׂנְאֵי צַדִּיק יֶאְשָׁמוּ; פּוֹדֶה י~הוה נֶפֶשׁ עֲבָדָיו, וְלא יֶאְשְׁמוּ כּKל הַחוֹסִים בּוֹ;

תְּפִלָּה לְמֹשֶׁה אִישׁ הָאֱ~לֹהִים, אֲ~דֹנָי מָעוֹן אַתָּה הָיִיתָ לָּנוּ, בְּדוֹר וָדֹר; בְּטֶרֶם הָרִים יֻלָּדוּ וַתְּחוֹלֵל אֶרֶץ וְתֵבֵל, וּמֵעוֹלָם עַד עוֹלָם אַתָּה אֵ~ל; תָּשֵׁב אֱנוֹשׁ עַד דַּכָּא, וַתֹּאמֶר שׁוּבוּ בְנֵי אָדָם; כִּי אֶלֶף שָׁנִים בְּעֵינֶיךָ כְּיוֹם אֶתְמול כִּי יַעֲבֹר, וְאַשְׁמוּרָה בַלָּיְלָה; זְרַמְתָּם שֵׁנָה יִהְיוּ, בַּבֹּקֶר כֶּחָצִיר יַחֲלֹף; בַּבֹּקֶר יָצִיץ וְחָלָף, לָעֶרֶב יְמוֹלֵל וְיָבֵשׁ; כִּי כָלִינוּ בְאַפֶּךָ, וּבַחֲמָתְךָ נִבְהָלְנוּ; שַׁתָּה עֲוׂנוֹתֵינוּ לְנֶגְדֶּךָ, עֲלֻמֵנוּ לִמְאוֹר פָּנֶיךָ; כִּי כKל יָמֵינוּ פָּנוּ בְעֶבְרָתֶךָ, כִּלִּינוּ שָׁנֵינוּ כְּמוֹ הֶגֶה; יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה, וְאִם בִּגְבוּרֹת שְׁמוֹנִים שָׁנָה, וְרKהְבָּם עָמָל וָאָוֶן, כִּי גָז חִישׁ וַנָּעֻפָה; מִי יוֹדֵעַ עֹז אַפֶּךָ, וּכְיִרְאָתְךָ עֶבְרָתֶךָ; לִמְנוֹת יָמֵינוּ כֵּן הוֹדַע, וְנָבִיא לְבַב חKכְמָה; שׁוּבָה י~הוה עַד מָתָי, וְהִנָּחֵם עַל עֲבָדֶיךָ; שַׂבְּעֵנוּ בַבֹּקֶר חַסְדֶּךָ, וּנְרַנְּנָה וְנִשמְחָה בְּכKל יָמֵינוּ; שַׂמְּחֵנוּ כִּימות עִנִּיתָנוּ, שְׁנוֹת רָאִינוּ רָעָה; יֵרָאֶה אֶל עֲבָדֶיךָ פָעֳלֶךָ, וַהֲדָרְךָ עַל בְּנֵיהֶם; וִיהִי נֹעַם אֲ~דֹנָי אֱ~לֹהֵינוּ עָלֵינוּ, וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ, וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנֵהוּ;

יֹשֵׁב בְּסֵתֶר עֶלְיוֹן, בְּצֵל שַׁ~דַּי יִתְלוֹנָן; אֹמַר לַי~הוה מַחְסִי וּמְצוּדָתִי, אֱ~לֹהַי אֶבְטַח בּוֹ; כִּי הוּא יַצִּילְךָ מִפַּח יָקוּשׁ, מִדֶּבֶר הַוּוֹת; בְּאֶבְרָתו יָסֶךְ לָךְ, וְתַחַת כְּנָפָיו תֶּחְסֶה, צִנָּה וְסוֹחֵרָה אֲמִתּוֹ; לא תִירָא מִפַּחַד לָיְלָה, מֵחֵץ יָעוּף יוֹמָם; מִדֶּבֶר בָּאֹפֶל יַהֲלֹךְ, מִקֶּטֶב יָשׁוּד צָהֳרָיִם; יִפֹּל מִצִּדְּךָ אֶלֶף וּרְבָבָה מִימִינֶךָ, אֵלֶיךָ לֹא יִגָּשׁ; רַק בְּעֵינֶיךָ תַבִּיט, וְשִׁלֻּמַת רְשָׁעִים תִּרְאֶה; כִּי אַתָּה י~הוה מַחְסִי, עֶלְיוֹן שמְתָּ מְעוֹנֶךָ; לא תְאֻנֶּה אֵלֶיךָ רָעָה, וְנֶגַע לא יִקְרַב בְּאָהֳלֶךָ; כִּי מַלְאָכָיו יְצַוֶּה לָּךְ, לִשְׁמKרְךָ בְּכKל דְּרָכֶיךָ; עַל כַּפַּיִם יִשָּׂאוּנְךָ, פֶּן תִּגּוֹף בָּאֶבֶן רַגְלֶךָ; עַל שַׁחַל וָפֶתֶן תִּדְרוֹךְ, תִּרְמוֹס כְּפִיר וְתַנִּין; כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ, אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי; יִקְרָאֵנִי וְאֶעֱנֵהוּ, עִמּוֹ אָנֹכִי בְצָרָה, אֲחַלְּצֵהוּ וַאֲכַבְּדֵהוּ; אֹרֶךְ יָמִים אַשְׂבִּיעֵהוּ, וְאַרְאֵהוּ בִּישׁוּעָתִי; אֹרֶךְ יָמִים אַשְׂבִּיעֵהוּ, וְאַרְאֵהוּ בִּישׁוּעָתִי;

מִזְמוֹר שִׁירוּ לַי~הוה שִׁיר חָדָשׁ, כִּי נִפְלָאוֹת עָשָׂה; הוֹשִׁיעָה לּוֹ יְמִינוֹ וּזְרוֹעַ קKדְשׁוֹ; הוֹדִיעַ י~הוה יְשׁוּעָתוֹ, לְעֵינֵי הַגּוֹיִם גִּלָּה צִדְקָתוֹ; זָכַר חַסְדּוֹ וֶאֱמוּנָתוֹ לְבֵית יִשְׂרָאֵל, רָאוּ כKל אַפְסֵי אָרֶץ אֵת יְשׁוּעַת אֱ~לֹהֵינוּ; הָרִיעוּ לַי~הוה כּKל הָאָרֶץ, פִּצְחוּ וְרַנְּנוּ וְזַמֵּרוּ; זַמְּרוּ לַי~הוה בְּכִנּוֹר, בְּכִנּוֹר וְקוֹל זִמְרָה; בַּחֲצֹצְרוֹת וְקוֹל שׁוֹפָר, הָרִיעוּ לִפְנֵי הַמֶּלֶךְ י~הוה; יִרְעַם הַיָּם וּמְלֹאוֹ, תֵּבֵל וְיֹשְׁבֵי בָהּ; נְהָרוֹת יִמְחֲאוּ כָף, יַחַד הָרִים יְרַנֵּנוּ; לִפְנֵי י~הוה כִּי בָא לִשְׁפֹּט הָאָרֶץ, יִשְׁפֹּט תֵּבֵל בְּצֶדֶק וְעַמִּים בְּמֵישָׁרִים;

שִׁיר לַמַּעֲלוֹת, אֶשָּׂא עֵינַי אֶל הֶהָרִים, מֵאַיִן יָבֹא עֶזְרִי; עֶזְרִי מֵעִם י~הוה, עֹשֵׂה שָׁמַיִם וָאָרֶץ; אַל יִתֵּן לַמּוֹט רַגְלֶךָ, אַל יָנוּם שֹׁמְרֶךָ; הִנֵּה לֹא יָנוּם וְלֹא יִישָׁן שׁוֹמֵר יִשְׂרָאֵל; י~הוה שֹׁמְרֶךָ, י~הוה צִלְּךָ עַל יַד יְמִינֶךָ; יוֹמָם הַשֶּׁמֶשׁ לֹא יַכֶּכָּה, וְיָרֵחַ בַּלָּיְלָה; י~הוה יִשְׁמKרְךָ מִכּKל רָע, יִשְׁמֹר אֶת נַפְשֶׁךָ; י~הוה יִשְׁמKר צֵאתְךָ וּבוֹאֶךָ, מֵעַתָּה וְעַד עוֹלָם;

שִׁיר הַמַּעֲלוֹת לְדָוִד, שָׂמַחְתִּי בְּאֹמְרִים לִי בֵּית י~הוה נֵלֵךְ; עֹמְדוֹת הָיוּ רַגְלֵינוּ בִּשְׁעָרַיִךְ יְרוּשָׁלָיִם; יְרוּשָׁלַיִם הַבְּנוּיָה, כְּעִיר שֶׁחֻבְּרָה לָהּ יַחְדָּו; שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָ~הּ עֵדוּת לְיִשְׂרָאֵל, לְהוֹדוֹת לְשֵׁם י~הוה; כִּי שָׁמָּה יָשְׁבוּ כִסְאוֹת לְמִשְׁפָּט, כִּסְאוֹת לְבֵית דָּוִד; שַׁאֲלוּ שְׁלוֹם יְרוּשָׁלָיִם, יִשְׁלָיוּ אֹהֲבָיִךְ; יְהִי שָׁלוֹם בְּחֵילֵךְ, שַׁלְוָה בְּאַרְמְנֹתָיִךְ; לְמַעַן אַחַי וְרֵעָי, אֲדַבְּרָה נָּא שָׁלוֹם בָּךְ; לְמַעַן בֵּית י~הוה אֱ~לֹהֵינוּ, אֲבַקְשָׁה טוֹב לָךְ;

שִׁיר הַמַּעֲלוֹת, אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי הַיּוֹשְׁבִי בַּשָּׁמָיִם; הִנֵּה כְעֵינֵי עֲבָדִים אֶל יַד אֲדוֹנֵיהֶם, כְּעֵינֵי שִׁפְחָה אֶל יַד גְּבִרְתָּהּ, כֵּן עֵינֵינוּ אֶל י~הוה אֱ~לֹהֵינוּ עַד שֶׁיְּחKנֵּנוּ; חKנֵּנוּ י~הוה חKנֵּנוּ, כִּי רַב שָׂבַעְנוּ בוּז; רַבַּת שָׂבְעָה לָּהּ נַפְשֵׁנוּ הַלַּעַג הַשַּׁאֲנַנִּים, הַבּוּז לִגְאֵי יוֹנִים;

שִׁיר הַמַּעֲלוֹת לְדָוִד, לוּלֵי י~הוה שֶׁהָיָה לָנוּ יֹאמַר נָא יִשְׂרָאֵל; לוּלֵי י~הוה שֶׁהָיָה לָנוּ, בְּקוּם עָלֵינוּ אָדָם; אֲזַי חַיִּים בְּלָעוּנוּ, בַּחֲרוֹת אַפָּם בָּנוּ; אֲזַי הַמַּיִם שְׁטָפוּנוּ, נַחְלָה עָבַר עַל נַפְשֵׁנוּ; אֲזַי עָבַר עַל נַפְשֵׁנוּ, הַמַּיִם הַזֵּידוֹנִים; בָּרוּךְ י~הוה, שֶׁלֹּא נְתָנָנוּ טֶרֶף לְשִׁנֵּיהֶם; נַפְשֵׁנוּ כְּצִפּוֹר נִמְלְטָה מִפַּח יוֹקְשִׁים, הַפַּח נִשְׁבָּר וַאֲנַחְנוּ נִמְלָטְנוּ; עֶזְרֵנוּ בְּשֵׁם י~הוה, עֹשֵׂה שָׁמַיִם וָאָרֶץ;

