וַיְהִי הַמַּקְרִיב בַּיּוֹם הָרִאשׁוֹן אֶת קKרְבָּנוֹ, נַחְשׁוֹן בֶּן עַמִּינָדָב לְמַטֵּה יְהוּדָה; וְקKרְבָּנוֹ קַעֲרַת כֶּסֶף אַחַת, שְׁלֹשִׁים וּמֵאָה מִשְׁקָלָהּ, מִזְרָק אֶחָד כֶּסֶף שִׁבְעִים שֶׁקֶל בְּשֶׁקֶל הַקֹּדֶשׁ, שְׁנֵיהֶם מְלֵאִים סֹלֶת בְּלוּלָה בַשֶּׁמֶן לְמִנְחָה; כַּף אַחַת עֲשָׂרָה זָהָב מְלֵאָה קְטֹרֶת;
(:
שלישי
:)
פַּר אֶחָד בֶּן בָּקָר, אַיִל אֶחָד, כֶּבֶשׂ אֶחָד בֶּן שְׁנָתוֹ לְעֹלָה; שְׂעִיר עִזִּים אֶחָד לְחַטָּאת; וּלְזֶבַח הַשְּׁלָמִים בָּקָר שְׁנַיִם, אֵילִם חֲמִשָּׁה, עַתּוּדִים חֲמִשָּׁה, כְּבָשִׂים בְּנֵי שָׁנָה חֲמִשָּׁה, זֶה קKרְבַּן נַחְשׁוֹן בֶּן עַמִּינָדָב;

specials/tora_tzav:
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר זֹאת תּוֹרַת הָעֹלָה, הִוא הָעֹלָה עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כּKל הַלַּיְלָה עַד הַבֹּקֶר, וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּוֹ; וְלָבַשׁ הַכֹּהֵן מִדּוֹ בַד, וּמִכְנְסֵי בַד יִלְבַּשׁ עַל בְּשָׂרוֹ, וְהֵרִים אֶת הַדֶּשֶׁן אֲשֶׁר תֹּאכַל הָאֵשׁ אֶת הָעֹלָה עַל הַמִּזְבֵּחַ, וְשָׂמוֹ אֵצֶל הַמִּזְבֵּחַ;
(:
לוי
:)
וּפָשַׁט אֶת בְּגָדָיו וְלָבַשׁ בְּגָדִים אֲחֵרִים, וְהוֹצִיא אֶת הַדֶּשֶׁן אֶל מִחוּץ לַמַּחֲנֶה אֶל מָקוֹם טָהוֹר; וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ לֹא תִכְבֶּה, וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר, וְעָרַךְ עָלֶיהָ הָעֹלָה וְהִקְטִיר עָלֶיהָ חֶלְבֵי הַשְּׁלָמִים; אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה;
(:
שלישי
:)
וְזֹאת תּוֹרַת הַמִּנְחָה, הַקְרֵב אֹתָהּ בְּנֵי אַהֲרֹן לִפְנֵי י~הוה אֶל פְּנֵי הַמִּזְבֵּחַ; וְהֵרִים מִמֶּנּוּ בְּקֻמְצוֹ, מִסֹּלֶת הַמִּנְחָה וּמִשַּׁמְנָהּ וְאֵת כּKל הַלְּבֹנָה אֲשֶׁר עַל הַמִּנְחָה, וְהִקְטִיר הַמִּזְבֵּחַ רֵיחַ נִיחֹחַ אַזְכָּרָתָהּ לַי~הוה; וְהַנּוֹתֶרֶת מִמֶּנָּה יֹאכְלוּ אַהֲרֹן וּבָנָיו, מַצּוֹת תֵּאָכֵל בְּמָקוֹם קָדֹשׁ בַּחֲצַר אֹהֶל מוֹעֵד יֹאכְלוּהָ; לֹא תֵאָפֶה חָמֵץ, חֶלְקָם נָתַתִּי אֹתָהּ מֵאִשָּׁי, קֹדֶשׁ קָדָשִׁים הִוא כַּחַטָּאת וְכָאָשָׁם; כָּל זָכָר בִּבְנֵי אַהֲרֹן יֹאכְלֶנָּה, חKק עוֹלָם לְדֹרֹתֵיכֶם מֵאִשֵּׁי י~הוה, כֹּל אֲשֶׁר יִגַּע בָּהֶם יִקְדָּשׁ;

specials/tora_vaychi:
וַיְחִי יַעֲקֹב בְּאֶרֶץ מִצְרַיִם שְׁבַע עֶשְׂרֵה שָׁנָה, וַיְהִי יְמֵי יַעֲקֹב שְׁנֵי חַיָּיו, שֶׁבַע שָׁנִים וְאַרְבָּעִים וּמְאַת שָׁנָה; וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת, וַיִּקְרָא לִבְנוֹ לְיוֹסֵף, וַיֹּאמֶר לוֹ אִם נָא מָצָאתִי חֵן בְּעֵינֶיךָ שִׂים נָא יָדְךָ תַּחַת יְרֵכִי, וְעָשִׂיתָ עִמָּדִי חֶסֶד וֶאֱמֶת אַל נָא תִקְבְּרֵנִי בְּמִצְרָיִם; וְשָׁכַבְתִּי עִם אֲבֹתַי וּנְשָׂאתַנִי מִמִּצְרַיִם וּקְבַרְתַּנִי בִּקְבֻרָתָם, וַיֹּאמַר אָנֹכִי אֶעֱשֶׂה כִדְבָרֶךָ; וַיֹּאמֶר הִשָּׁבְעָה לִי, וַיִּשָּׁבַע לוֹ, וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה;
(:
לוי
:)
וַיְהִי אַחֲרֵי הַדְּבָרִים הָאֵלֶּה, וַיֹּאמֶר לְיוֹסֵף הִנֵּה אָבִיךָ חֹלֶה, וַיִּקַּח אֶת שְׁנֵי בָנָיו עִמּוֹ, אֶת מְנַשֶּׁה וְאֶת אֶפְרָיִם; וַיַּגֵּד לְיַעֲקֹב, וַיֹּאמֶר הִנֵּה בִּנְךָ יוֹסֵף בָּא אֵלֶיךָ, וַיִּתְחַזֵּק יִשְׂרָאֵל וַיֵּשֶׁב עַל הַמִּטָּה; וַיֹּאמֶר יַעֲקֹב אֶל יוֹסֵף, אֵ~ל שַׁ~דַּי נִרְאָה אֵלַי בְּלוּז בְּאֶרֶץ כְּנָעַן, וַיְבָרֶךְ אֹתִי;
(:
שלישי
:)
וַיֹּאמֶר אֵלַי הִנְנִי מַפְרְךָ וְהִרְבִּיתִךָ וּנְתַתִּיךָ לִקְהַל עַמִּים, וְנָתַתִּי אֶת הָאָרֶץ הַזֹּאת לְזַרְעֲךָ אַחֲרֶיךָ אֲחֻזַּת עוֹלָם; וְעַתָּה שְׁנֵי בָנֶיךָ הַנּוֹלָדִים לְךָ בְּאֶרֶץ מִצְרַיִם עַד בֹּאִי אֵלֶיךָ מִצְרַיְמָה לִי הֵם, אֶפְרַיִם וּמְנַשֶּׁה כִּרְאוּבֵן וְשִׁמְעוֹן יִהְיוּ לִי; וּמוֹלַדְתְּךָ אֲשֶׁר הוֹלַדְתָּ אַחֲרֵיהֶם לְךָ יִהְיוּ, עַל שֵׁם אֲחֵיהֶם יִקָּרְאוּ בְּנַחֲלָתָם; וַאֲנִי בְּבֹאִי מִפַּדָּן מֵתָה עָלַי רָחֵל בְּאֶרֶץ כְּנַעַן בַּדֶּרֶךְ, בְּעוֹד כִּבְרַת אֶרֶץ לָבֹא אֶפְרָתָה, וָאֶקְבְּרֶהָ שָּׁם בְּדֶרֶךְ אֶפְרָת הִוא בֵּית לָחֶם; וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף, וַיֹּאמֶר מִי אֵלֶּה; וַיֹּאמֶר יוֹסֵף אֶל אָבִיו, בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱ~לֹהִים בָּזֶה, וַיֹּאמַר קָחֶם נָא אֵלַי וַאֲבָרְכֵם;

specials/tora_vayakhel:
וַיַּקְהֵל מֹשֶׁה אֶת כּKל עֲדַת בְּנֵי יִשְׂרָאֵל וַיֹּאמֶר אֲלֵהֶם, אֵלֶּה הַדְּבָרִים אֲשֶׁר צִוָּה י~הוה לַעֲשֹׂת אֹתָם; שֵׁשֶׁת יָמִים תֵּעָשֶׂה מְלָאכָה, וּבַיּוֹם הַשְּׁבִיעִי יִהְיֶה לָכֶם קֹדֶשׁ שַׁבַּת שַׁבָּתוֹן לַי~הוה, כּKל הָעֹשֶׂה בוֹ מְלָאכָה יוּמָת; לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבֹתֵיכֶם, בְּיוֹם הַשַּׁבָּת;
(:
לוי
:)
וַיֹּאמֶר מֹשֶׁה אֶל כּKל עֲדַת בְּנֵי יִשְׂרָאֵל לֵאמֹר, זֶה הַדָּבָר אֲשֶׁר צִוָּה י~הוה לֵאמֹר; קְחוּ מֵאִתְּכֶם תְּרוּמָה לַי~הוה, כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ אֵת תְּרוּמַת י~הוה, זָהָב וָכֶסֶף וּנְחֹשֶׁת; וּתְכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי וְשֵׁשׁ וְעִזִּים; וְעֹרֹת אֵילִם מְאKדָּמִים וְעֹרֹת תְּחָשִׁים וַעֲצֵי שִׁטִּים; וְשֶׁמֶן לַמָּאוֹר, וּבְשָׂמִים לְשֶׁמֶן הַמִּשְׁחָה וְלִקְטֹרֶת הַסַּמִּים; וְאַבְנֵי שֹׁהַם וְאַבְנֵי מִלֻּאִים, לָאֵפוֹד וְלַחֹשֶׁן; וְכKל חֲכַם לֵב בָּכֶם, יָבֹאוּ וְיַעֲשׂוּ אֵת כּKל אֲשֶׁר צִוָּה י~הוה;
(:
שלישי
:)
אֶת הַמִּשְׁכָּן אֶת אָהֳלוֹ וְאֶת מִכְסֵהוּ, אֶת קְרָסָיו וְאֶת קְרָשָׁיו, אֶת בְּרִיחָו, אֶת עַמֻּדָיו וְאֶת אֲדָנָיו; אֶת הָאָרֹן וְאֶת בַּדָּיו אֶת הַכַּפֹּרֶת, וְאֵת פָּרֹכֶת הַמָּסָךְ; אֶת הַשֻּׁלְחָן וְאֶת בַּדָּיו וְאֶת כּKל כֵּלָיו, וְאֵת לֶחֶם הַפָּנִים; וְאֶת מְנֹרַת הַמָּאוֹר וְאֶת כֵּלֶיהָ וְאֶת נֵרֹתֶיהָ, וְאֵת שֶׁמֶן הַמָּאוֹר; וְאֶת מִזְבַּח הַקְּטֹרֶת וְאֶת בַּדָּיו, וְאֵת שֶׁמֶן הַמִּשְׁחָה וְאֵת קְטֹרֶת הַסַּמִּים וְאֶת מָסַךְ הַפֶּתַח לְפֶתַח הַמִּשְׁכָּן; אֵת מִזְבַּח הָעֹלָה וְאֶת מִכְבַּר הַנְּחֹשֶׁת אֲשֶׁר לוֹ, אֶת בַּדָּיו וְאֶת כּKל כֵּלָיו, אֶת הַכִּיֹּר וְאֶת כַּנּוֹ; אֵת קַלְעֵי הֶחָצֵר אֶת עַמֻּדָיו וְאֶת אֲדָנֶיהָ, וְאֵת מָסַךְ שַׁעַר הֶחָצֵר; אֶת יִתְדֹת הַמִּשְׁכָּן וְאֶת יִתְדֹת הֶחָצֵר וְאֶת מֵיתְרֵיהֶם; אֶת בִּגְדֵי הַשְּׂרָד לְשָׁרֵת בַּקֹּדֶשׁ, אֶת בִּגְדֵי הַקֹּדֶשׁ לְאַהֲרֹן הַכֹּהֵן וְאֶת בִּגְדֵי בָנָיו לְכַהֵן; וַיֵּצְאוּ כּKל עֲדַת בְּנֵי יִשְׂרָאֵל מִלִּפְנֵי מֹשֶׁה;

specials/tora_emor:
וַיֹּאמֶר י~הוה אֶל מֹשֶׁה אֱמֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן, וְאָמַרְתָּ אֲלֵהֶם לְנֶפֶשׁ לֹא יִטַּמָּא בְּעַמָּיו; כִּי אִם לִשְׁאֵרוֹ הַקָּרֹב אֵלָיו, לְאִמּוֹ וּלְאָבִיו וְלִבְנוֹ וּלְבִתּוֹ וּלְאָחִיו; וְלַאֲחֹתוֹ הַבְּתוּלָה הַקְּרוֹבָה אֵלָיו אֲשֶׁר לֹא הָיְתָה לְאִישׁ, לָהּ יִטַּמָּא; לֹא יִטַּמָּא בַּעַל בְּעַמָּיו, לְהֵחַלּוֹ; לֹא יִקְרְחֻה קKרְחָה בְּרֹאשָׁם וּפְאַת זְקָנָם לֹא יְגַלֵּחוּ, וּבִבְשָׂרָם לֹא יִשְׂרְטוּ שָׂרָטֶת; קְדֹשִׁים יִהְיוּ לֵא~לֹהֵיהֶם וְלֹא יְחַלְּלוּ שֵׁם אֱ~לֹהֵיהֶם, כִּי אֶת אִשֵּׁי י~הוה לֶחֶם אֱ~לֹהֵיהֶם הֵם מַקְרִיבִם וְהָיוּ קֹדֶשׁ;
(:
לוי
:)
