וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; שְׁלַח לְךָ אֲנָשִׁים וְיָתֻרוּ אֶת אֶרֶץ כְּנַעַן אֲשֶׁר אֲנִי נֹתֵן לִבְנֵי יִשְׂרָאֵל, אִישׁ אֶחָד אִישׁ אֶחָד לְמַטֵּה אֲבֹתָיו תִּשְׁלָחוּ, כֹּל נָשִׂיא בָהֶם; וַיִּשְׁלַח אֹתָם מֹשֶׁה מִמִּדְבַּר פָּארָן עַל פִּי י~הוה, כֻּלָּם אֲנָשִׁים רָאשֵׁי בְנֵי יִשְׂרָאֵל הֵמָּה;
(:
לוי
:)
וְאֵלֶּה שְׁמוֹתָם, לְמַטֵּה רְאוּבֵן שַׁמּוּעַ בֶּן זַכּוּר; לְמַטֵּה שִׁמְעוֹן שָׁפָט בֶּן חוֹרִי; לְמַטֵּה יְהוּדָה כָּלֵב בֶּן יְפֻנֶּה; לְמַטֵּה יִשָּׂשכָר יִגְאָל בֶּן יוֹסֵף; לְמַטֵּה אֶפְרָיִם הוֹשֵׁעַ בִּן נוּן; לְמַטֵּה בִנְיָמִן פַּלְטִי בֶּן רָפוּא; לְמַטֵּה זְבוּלֻן גַּדִּיאֵל בֶּן סוֹדִי; לְמַטֵּה יוֹסֵף לְמַטֵּה מְנַשֶּׁה, גַּדִּי בֶּן סוּסִי; לְמַטֵּה דָן עַמִּיאֵל בֶּן גְּמַלִּי; לְמַטֵּה אָשֵׁר סְתוּר בֶּן מִיכָאֵל; לְמַטֵּה נַפְתָּלִי נַחְבִּי בֶּן וKפְסִי; לְמַטֵּה גָד גְּאוּאֵל בֶּן מָכִי; אֵלֶּה שְׁמוֹת הָאֲנָשִׁים אֲשֶׁר שָׁלַח מֹשֶׁה לָתוּר אֶת הָאָרֶץ, וַיִּקְרָא מֹשֶׁה לְהוֹשֵׁעַ בִּן נוּן יְהוֹשֻׁעַ;
(:
שלישי
:)
וַיִּשְׁלַח אֹתָם מֹשֶׁה לָתוּר אֶת אֶרֶץ כְּנָעַן, וַיֹּאמֶר אֲלֵהֶם עֲלוּ זֶה בַּנֶּגֶב וַעֲלִיתֶם אֶת הָהָר; וּרְאִיתֶם אֶת הָאָרֶץ מַה הִוא, וְאֶת הָעָם הַיֹּשֵׁב עָלֶיהָ הֶחָזָק הוּא הֲרָפֶה הַמְעַט הוּא אִם רָב; וּמָה הָאָרֶץ אֲשֶׁר הוּא יֹשֵׁב בָּהּ הֲטוֹבָה הִוא אִם רָעָה, וּמָה הֶעָרִים אֲשֶׁר הוּא יוֹשֵׁב בָּהֵנָּה הַבְּמַחֲנִים אִם בְּמִבְצָרִים; וּמָה הָאָרֶץ הַשְּׁמֵנָה הִוא אִם רָזָה הֲיֵשׁ בָּהּ עֵץ אִם אַיִן, וְהִתְחַזַּקְתֶּם וּלְקַחְתֶּם מִפְּרִי הָאָרֶץ, וְהַיָּמִים יְמֵי בִּכּוּרֵי עֲנָבִים;

specials/tora_vaera:
וַיְדַבֵּר אֱ~לֹהִים אֶל מֹשֶׁה, וַיֹּאמֶר אֵלָיו אֲנִי י~הוה; וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵ~ל שַׁ~דָּי, וּשְׁמִי י~הוה לֹא נוֹדַעְתִּי לָהֶם; וְגַם הֲקִמֹתִי אֶת בְּרִיתִי אִתָּם לָתֵת לָהֶם אֶת אֶרֶץ כְּנָעַן, אֵת אֶרֶץ מְגֻרֵיהֶם אֲשֶׁר גָּרוּ בָהּ; וְגַם אֲנִי שָׁמַעְתִּי אֶת נַאֲקַת בְּנֵי יִשְׂרָאֵל אֲשֶׁר מִצְרַיִם מַעֲבִדִים אֹתָם, וָאֶזְכֹּר אֶת בְּרִיתִי;
(:
לוי
:)
 לָכֵן אֱמֹר לִבְנֵי יִשְׂרָאֵל אֲנִי י~הוה, וְהוֹצֵאתִי אֶתְכֶם מִתַּחַת סִבְלֹת מִצְרַיִם וְהִצַּלְתִּי אֶתְכֶם מֵעֲבֹדָתָם, וְגָאַלְתִּי אֶתְכֶם בִּזְרוֹעַ נְטוּיָה וּבִשְׁפָטִים גְּדֹלִים; וְלָקַחְתִּי אֶתְכֶם לִי לְעָם וְהָיִיתִי לָכֶם לֵא~לֹהִים, וִידַעְתֶּם כִּי אֲנִי י~הוה אֱ~לֹהֵיכֶם הַמּוֹצִיא אֶתְכֶם מִתַּחַת סִבְלוֹת מִצְרָיִם; וְהֵבֵאתִי אֶתְכֶם אֶל הָאָרֶץ, אֲשֶׁר נָשָׂאתִי אֶת יָדִי לָתֵת אֹתָהּ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב, וְנָתַתִּי אֹתָהּ לָכֶם מוֹרָשָׁה אֲנִי י~הוה; וַיְדַבֵּר מֹשֶׁה כֵּן אֶל בְּנֵי יִשְׂרָאֵל, וְלֹא שָׁמְעוּ אֶל מֹשֶׁה מִקֹּצֶר רוּחַ וּמֵעֲבֹדָה קָשָׁה;
(:
שלישי
:)
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; בֹּא דַבֵּר אֶל פַּרְעֹה מֶלֶךְ מִצְרָיִם, וִישַׁלַּח אֶת בְּנֵי יִשְׂרָאֵל מֵאַרְצוֹ; וַיְדַבֵּר מֹשֶׁה לִפְנֵי י~הוה לֵאמֹר, הֵן בְּנֵי יִשְׂרָאֵל לֹא שָׁמְעוּ אֵלַי, וְאֵיךְ יִשְׁמָעֵנִי פַרְעֹה וַאֲנִי עֲרַל שְׂפָתָיִם; וַיְדַבֵּר י~הוה אֶל מֹשֶׁה וְאֶל אַהֲרֹן, וַיְצַוֵּם אֶל בְּנֵי יִשְׂרָאֵל וְאֶל פַּרְעֹה מֶלֶךְ מִצְרָיִם, לְהוֹצִיא אֶת בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם;

specials/tora_bo:
וַיֹּאמֶר י~הוה אֶל מֹשֶׁה בֹּא אֶל פַּרְעֹה, כִּי אֲנִי הִכְבַּדְתִּי אֶת לִבּוֹ וְאֶת לֵב עֲבָדָיו, לְמַעַן שִׁתִי אֹתֹתַי אֵלֶּה בְּקִרְבּוֹ; וּלְמַעַן תְּסַפֵּר בְּאKזְנֵי בִנְךָ וּבֶן בִּנְךָ אֵת אֲשֶׁר הִתְעַלַּלְתִּי בְּמִצְרַיִם וְאֶת אֹתֹתַי אֲשֶׁר שַׂמְתִּי בָם, וִידַעְתֶּם כִּי אֲנִי י~הוה; וַיָּבֹא מֹשֶׁה וְאַהֲרֹן אֶל פַּרְעֹה, וַיֹּאמְרוּ אֵלָיו כֹּה אָמַר י~הוה אֱ~לֹהֵי הָעִבְרִים עַד מָתַי מֵאַנְתָּ לֵעָנֹת מִפָּנָי, שַׁלַּח עַמִּי וְיַעַבְדֻנִי;
(:
לוי
:)
כִּי אִם מָאֵן אַתָּה לְשַׁלֵּחַ אֶת עַמִּי, הִנְנִי מֵבִיא מָחָר אַרְבֶּה בִּגְבֻלֶךָ; וְכִסָּה אֶת עֵין הָאָרֶץ וְלֹא יוּכַל לִרְאֹת אֶת הָאָרֶץ, וְאָכַל אֶת יֶתֶר הַפְּלֵטָה הַנִּשְׁאֶרֶת לָכֶם מִן הַבָּרָד, וְאָכַל אֶת כּKל הָעֵץ הַצֹּמֵחַ לָכֶם מִן הַשָּׂדֶה; וּמָלְאוּ בָתֶּיךָ וּבָתֵּי כKל עֲבָדֶיךָ וּבָתֵּי כKל מִצְרַיִם, אֲשֶׁר לֹא רָאוּ אֲבֹתֶיךָ וַאֲבוֹת אֲבֹתֶיךָ מִיּוֹם הֱיוֹתָם עַל הָאֲדָמָה עַד הַיּוֹם הַזֶּה, וַיִּפֶן וַיֵּצֵא מֵעִם פַּרְעֹה;
(:
שלישי
:)
וַיֹּאמְרוּ עַבְדֵי פַרְעֹה אֵלָיו, עַד מָתַי יִהְיֶה זֶה לָנוּ לְמוֹקֵשׁ, שַׁלַּח אֶת הָאֲנָשִׁים וְיַעַבְדוּ אֶת י~הוה אֱ~לֹהֵיהֶם, הֲטֶרֶם תֵּדַע כִּי אָבְדָה מִצְרָיִם; וַיּוּשַׁב אֶת מֹשֶׁה וְאֶת אַהֲרֹן אֶל פַּרְעֹה, וַיֹּאמֶר אֲלֵהֶם לְכוּ עִבְדוּ אֶת י~הוה אֱ~לֹהֵיכֶם, מִי וָמִי הַהֹלְכִים; וַיֹּאמֶר מֹשֶׁה בִּנְעָרֵינוּ וּבִזְקֵנֵינוּ נֵלֵךְ, בְּבָנֵינוּ וּבִבְנוֹתֵנוּ בְּצֹאנֵנוּ וּבִבְקָרֵנוּ נֵלֵךְ, כִּי חַג י~הוה לָנוּ; וַיֹּאמֶר אֲלֵהֶם יְהִי כֵן י~הוה עִמָּכֶם כַּאֲשֶׁר אֲשַׁלַּח אֶתְכֶם וְאֶת טַפְּכֶם, רְאוּ כִּי רָעָה נֶגֶד פְּנֵיכֶם; לֹא כֵן לְכוּ נָא הַגְּבָרִים וְעִבְדוּ אֶת י~הוה, כִּי אֹתָהּ אַתֶּם מְבַקְשִׁים, וַיְגָרֶשׁ אֹתָם מֵאֵת פְּנֵי פַרְעֹה;

specials/tora_tishaa_beav:
כִּי תוֹלִיד בָּנִים וּבְנֵי בָנִים וְנוֹשַׁנְתֶּם בָּאָרֶץ, וְהִשְׁחַתֶּם וַעֲשִׂיתֶם פֶּסֶל תְּמוּנַת כֹּל, וַעֲשִׂיתֶם הָרַע בְּעֵינֵי י~הוה אֱ~לֹהֶיךָ לְהַכְעִיסוֹ; הַעִידֹתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ כִּי אָבֹד תֹּאבֵדוּן מַהֵר מֵעַל הָאָרֶץ אֲשֶׁר אַתֶּם עֹבְרִים אֶת הַיַּרְדֵּן שָׁמָּה לְרִשְׁתָּהּ, לֹא תַאֲרִיכֻן יָמִים עָלֶיהָ כִּי הִשָּׁמֵד תִּשָּׁמֵדוּן; וְהֵפִיץ י~הוה אֶתְכֶם בָּעַמִּים, וְנִשְׁאַרְתֶּם מְתֵי מִסְפָּר בַּגּוֹיִם אֲשֶׁר יְנַהֵג י~הוה אֶתְכֶם שָׁמָּה; וַעֲבַדְתֶּם שָׁם אֱלֹהִים מַעֲשֵׂה יְדֵי אָדָם, עֵץ וָאֶבֶן אֲשֶׁר לֹא יִרְאוּן וְלֹא יִשְׁמְעוּן וְלֹא יֹאכְלוּן וְלֹא יְרִיחֻן; וּבִקַּשְׁתֶּם מִשָּׁם אֶת י~הוה אֱ~לֹהֶיךָ וּמָצָאתָ, כִּי תִדְרְשֶׁנּוּ בְּכKל לְבָבְךָ וּבְכKל נַפְשֶׁךָ;
(:
לוי
:)
בַּצַּר לְךָ וּמְצָאוּךָ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים, וְשַׁבְתָּ עַד י~הוה אֱ~לֹהֶיךָ וְשָׁמַעְתָּ בְּקֹלוֹ; כִּי אֵ~ל רַחוּם י~הוה אֱ~לֹהֶיךָ, לֹא יַרְפְּךָ וְלֹא יַשְׁחִיתֶךָ, וְלֹא יִשְׁכַּח אֶת בְּרִית אֲבֹתֶיךָ אֲשֶׁר נִשְׁבַּע לָהֶם; כִּי שְׁאַל נָא לְיָמִים רִאשֹׁנִים אֲשֶׁר הָיוּ לְפָנֶיךָ, לְמִן הַיּוֹם אֲשֶׁר בָּרָא אֱ~לֹהִים אָדָם עַל הָאָרֶץ וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם, הֲנִהְיָה כַּדָּבָר הַגָּדוֹל הַזֶּה אוֹ הֲנִשְׁמַע כָּמֹהוּ; הֲשָׁמַע עָם קוֹל אֱ~לֹהִים מְדַבֵּר מִתּוֹךְ הָאֵשׁ כַּאֲשֶׁר שָׁמַעְתָּ אַתָּה וַיֶּחִי; אוֹ הֲנִסָּה אֱ~לֹהִים לָבוֹא לָקַחַת לוֹ גוֹי מִקֶּרֶב גּוֹי, בְּמַסֹּת בְּאֹתֹת וּבְמוֹפְתִים וּבְמִלְחָמָה וּבְיָד חֲזָקָה וּבִזְרוֹעַ נְטוּיָה וּבְמוֹרָאִים גְּדֹלִים, כְּכֹל אֲשֶׁר עָשָׂה לָכֶם י~הוה אֱ~לֹהֵיכֶם בְּמִצְרַיִם לְעֵינֶיךָ; אַתָּה הKרְאֵתָ לָדַעַת כִּי י~הוה הוּא הָאֱ~לֹהִים, אֵין עוֹד מִלְבַדּוֹ;
(:
שלישי
:)
מִן הַשָּׁמַיִם הִשְׁמִיעֲךָ אֶת קֹלוֹ לְיַסְּרֶךָּ, וְעַל הָאָרֶץ הֶרְאֲךָ אֶת אִשּׁוֹ הַגְּדוֹלָה וּדְבָרָיו שָׁמַעְתָּ מִתּוֹךְ הָאֵשׁ; וְתַחַת כִּי אָהַב אֶת אֲבֹתֶיךָ וַיִּבְחַר בְּזַרְעוֹ אַחֲרָיו, וַיּוֹצִאֲךָ בְּפָנָיו בְּכֹחוֹ הַגָּדֹל מִמִּצְרָיִם; לְהוֹרִישׁ גּוֹיִם גְּדֹלִים וַעֲצֻמִים מִמְּךָ מִפָּנֶיךָ, לַהֲבִיאֲךָ לָתֶת לְךָ אֶת אַרְצָם נַחֲלָה כַּיּוֹם הַזֶּה; וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבֹתָ אֶל לְבָבֶךָ, כִּי י~הוה הוּא הָאֱ~לֹהִים בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת, אֵין עוֹד; וְשָׁמַרְתָּ אֶת חֻקָּיו וְאֶת מִצְוׂתָיו אֲשֶׁר אָנֹכִי מְצַוְּךָ הַיּוֹם, אֲשֶׁר יִיטַב לְךָ וּלְבָנֶיךָ אַחֲרֶיךָ וּלְמַעַן תַּאֲרִיךְ יָמִים עַל הָאֲדָמָה אֲשֶׁר י~הוה אֱ~לֹהֶיךָ נֹתֵן לְךָ כּKל הַיָּמִים;

specials/tora_vayikra:
וַיִּקְרָא אֶל מֹשֶׁה, וַיְדַבֵּר י~הוה אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר; דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם, אָדָם כִּי יַקְרִיב מִכֶּם קKרְבָּן לַי~הוה, מִן הַבְּהֵמָה מִן הַבָּקָר וּמִן הַצֹּאן תַּקְרִיבוּ אֶת קKרְבַּנְכֶם; אִם עֹלָה קKרְבָּנוֹ מִן הַבָּקָר, זָכָר תָּמִים יַקְרִיבֶנּוּ, אֶל פֶּתַח אֹהֶל מוֹעֵד יַקְרִיב אֹתוֹ, לִרְצֹנוֹ לִפְנֵי י~הוה; וְסָמַךְ יָדוֹ עַל רֹאשׁ הָעֹלָה, וְנִרְצָה לוֹ לְכַפֵּר עָלָיו;
(:
לוי
:)
וְשָׁחַט אֶת בֶּן הַבָּקָר לִפְנֵי י~הוה, וְהִקְרִיבוּ בְּנֵי אַהֲרֹן הַכֹּהֲנִים אֶת הַדָּם, וְזָרְקוּ אֶת הַדָּם עַל הַמִּזְבֵּחַ סָבִיב, אֲשֶׁר פֶּתַח אֹהֶל מוֹעֵד; וְהִפְשִׁיט אֶת הָעֹלָה, וְנִתַּח אֹתָהּ לִנְתָחֶיהָ; וְנָתְנוּ בְּנֵי אַהֲרֹן הַכֹּהֵן אֵשׁ עַל הַמִּזְבֵּחַ, וְעָרְכוּ עֵצִים עַל הָאֵשׁ; וְעָרְכוּ בְּנֵי אַהֲרֹן הַכֹּהֲנִים אֵת הַנְּתָחִים אֶת הָרֹאשׁ וְאֶת הַפָּדֶר, עַל הָעֵצִים אֲשֶׁר עַל הָאֵשׁ אֲשֶׁר עַל הַמִּזְבֵּחַ; וְקִרְבּוֹ וּכְרָעָיו יִרְחַץ בַּמָּיִם, וְהִקְטִיר הַכֹּהֵן אֶת הַכֹּל הַמִּזְבֵּחָה, עֹלָה אִשֵּׁה רֵיחַ נִיחוֹחַ לַי~הוה;
(:
שלישי
:)
וְאִם מִן הַצֹּאן קKרְבָּנוֹ מִן הַכְּשָׂבִים אוֹ מִן הָעִזִּים לְעֹלָה, זָכָר תָּמִים יַקְרִיבֶנּוּ; וְשָׁחַט אֹתוֹ עַל יֶרֶךְ הַמִּזְבֵּחַ צָפֹנָה לִפְנֵי י~הוה, וְזָרְקוּ בְּנֵי אַהֲרֹן הַכֹּהֲנִים אֶת דָּמוֹ עַל הַמִּזְבֵּחַ סָבִיב; וְנִתַּח אֹתוֹ לִנְתָחָיו וְאֶת רֹאשׁוֹ וְאֶת פִּדְרוֹ, וְעָרַךְ הַכֹּהֵן אֹתָם עַל הָעֵצִים אֲשֶׁר עַל הָאֵשׁ אֲשֶׁר עַל הַמִּזְבֵּחַ; וְהַקֶּרֶב וְהַכְּרָעַיִם יִרְחַץ בַּמָּיִם, וְהִקְרִיב הַכֹּהֵן אֶת הַכֹּל וְהִקְטִיר הַמִּזְבֵּחָה עֹלָה הוּא אִשֵּׁה רֵיחַ נִיחֹחַ לַי~הוה;

specials/tora_vayishlach:
וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים לְפָנָיו אֶל עֵשָׂו אָחִיו, אַרְצָה שֵׂעִיר שְׂדֵה אֱדוֹם; וַיְצַו אֹתָם לֵאמֹר, כֹּה תֹאמְרוּן לַאדֹנִי לְעֵשָׂו, כֹּה אָמַר עַבְדְּךָ יַעֲקֹב, עִם לָבָן גַּרְתִּי וָאֵחַר עַד עָתָּה; וַיְהִי לִי שׁוֹר וַחֲמוֹר, צֹאן וְעֶבֶד וְשִׁפְחָה, וָאֶשְׁלְחָה לְהַגִּיד לַאדֹנִי לִמְצֹא חֵן בְּעֵינֶיךָ;
(:
לוי
:)
וַיָּשֻׁבוּ הַמַּלְאָכִים אֶל יַעֲקֹב לֵאמֹר, בָּאנוּ אֶל אָחִיךָ אֶל עֵשָׂו, וְגַם הֹלֵךְ לִקְרָאתְךָ וְאַרְבַּע מֵאוֹת אִישׁ עִמּוֹ; וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ, וַיַּחַץ אֶת הָעָם אֲשֶׁר אִתּוֹ וְאֶת הַצֹּאן וְאֶת הַבָּקָר וְהַגְּמַלִּים לִשְׁנֵי מַחֲנוֹת; וַיֹּאמֶר אִם יָבוֹא עֵשָׂו אֶל הַמַּחֲנֶה הָאַחַת וְהִכָּהוּ, וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה;
(:
שלישי
:)
וַיֹּאמֶר יַעֲקֹב, אֱ~לֹהֵי אָבִי אַבְרָהָם וֵא~לֹהֵי אָבִי יִצְחָק, י~הוה הָאֹמֵר אֵלַי שׁוּב לְאַרְצְךָ וּלְמוֹלַדְתְּךָ וְאֵיטִיבָה עִמָּךְ; קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכּKל הָאֱמֶת אֲשֶׁר עָשִׂיתָ אֶת עַבְדֶּךָ, כִּי בְמַקְלִי עָבַרְתִּי אֶת הַיַּרְדֵּן הַזֶּה וְעַתָּה הָיִיתִי לִשְׁנֵי מַחֲנוֹת; הַצִּילֵנִי נָא מִיַּד אָחִי מִיַּד עֵשָׂו, כִּי יָרֵא אָנֹכִי אֹתוֹ פֶּן יָבוֹא וְהִכַּנִי אֵם עַל בָּנִים; וְאַתָּה אָמַרְתָּ הֵיטֵב אֵיטִיב עִמָּךְ, וְשַׂמְתִּי אֶת זַרְעֲךָ כְּחוֹל הַיָּם אֲשֶׁר לֹא יִסָּפֵר מֵרֹב;

specials/tora_noach:
אֵלֶּה תּוֹלְדֹת נֹחַ, נֹחַ אִישׁ צַדִּיק תָּמִים הָיָה בְּדֹרֹתָיו, אֶת הָאֱ~לֹהִים הִתְהַלֶּךְ נֹחַ; וַיּוֹלֶד נֹחַ שְׁלֹשָׁה בָנִים, אֶת שֵׁם אֶת חָם וְאֶת יָפֶת; וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱ~לֹהִים, וַתִּמָּלֵא הָאָרֶץ חָמָס; וַיַּרְא אֱ~לֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה, כִּי הִשְׁחִית כּKל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ; וַיֹּאמֶר אֱ~לֹהִים לְנֹחַ, קֵץ כּKל בָּשָׂר בָּא לְפָנַי כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם, וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ; עֲשֵׂה לְךָ תֵּבַת עֲצֵי גֹפֶר, קִנִּים תַּעֲשֶׂה אֶת הַתֵּבָה, וְכָפַרְתָּ אֹתָהּ מִבַּיִת וּמִחוּץ בַּכֹּפֶר; וְזֶה אֲשֶׁר תַּעֲשֶׂה אֹתָהּ, שְׁלֹשׁ מֵאוֹת אַמָּה אֹרֶךְ הַתֵּבָה, חֲמִשִּׁים אַמָּה רKחְבָּהּ, וּשְׁלֹשִׁים אַמָּה קוֹמָתָהּ; צֹהַר תַּעֲשֶׂה לַתֵּבָה, וְאֶל אַמָּה תְּכַלֶנָּה מִלְמַעְלָה, וּפֶתַח הַתֵּבָה בְּצִדָּהּ תָּשִׂים, תַּחְתִּיִּם שְׁנִיִּם וּשְׁלִשִׁיִם תַּעֲשֶׂהָ;
(:
לוי
:)
וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם עַל הָאָרֶץ, לְשַׁחֵת כּKל בָּשָׂר אֲשֶׁר בּוֹ רוּחַ חַיִּים מִתַּחַת הַשָּׁמָיִם, כֹּל אֲשֶׁר בָּאָרֶץ יִגְוָע; וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ, וּבָאתָ אֶל הַתֵּבָה אַתָּה וּבָנֶיךָ וְאִשְׁתְּךָ וּנְשֵׁי בָנֶיךָ אִתָּךְ; וּמִכּKל הָחַי מִכּKל בָּשָׂר שְׁנַיִם מִכֹּל תָּבִיא אֶל הַתֵּבָה לְהַחֲיֹת אִתָּךְ, זָכָר וּנְקֵבָה יִהְיוּ;
(:
שלישי
:)
מֵהָעוֹף לְמִינֵהוּ וּמִן הַבְּהֵמָה לְמִינָהּ, מִכֹּל רֶמֶשׂ הָאֲדָמָה לְמִינֵהוּ, שְׁנַיִם מִכֹּל יָבֹאוּ אֵלֶיךָ לְהַחֲיוֹת; וְאַתָּה קַח לְךָ מִכּKל מַאֲכָל אֲשֶׁר יֵאָכֵל וְאָסַפְתָּ אֵלֶיךָ, וְהָיָה לְךָ וְלָהֶם לְאKכְלָה; וַיַּעַשׂ נֹחַ, כְּכֹל אֲשֶׁר צִוָּה אֹתוֹ אֱ~לֹהִים כֵּן עָשָׂה;

specials/tora_vayigash:
וַיִּגַּשׁ אֵלָיו יְהוּדָה, וַיֹּאמֶר בִּי אֲדֹנִי, יְדַבֶּר נָא עַבְדְּךָ דָבָר בְּאKזְנֵי אֲדֹנִי וְאַל יִחַר אַפְּךָ בְּעַבְדֶּךָ, כִּי כָמוֹךָ כְּפַרְעֹה; אֲדֹנִי שָׁאַל אֶת עֲבָדָיו לֵאמֹר, הֲיֵשׁ לָכֶם אָב אוֹ אָח; וַנֹּאמֶר אֶל אֲדֹנִי יֶשׁ לָנוּ אָב זָקֵן וְיֶלֶד זְקֻנִים קָטָן, וְאָחִיו מֵת וַיִּוָּתֵר הוּא לְבַדּוֹ לְאִמּוֹ וְאָבִיו אֲהֵבוֹ;
(:
לוי
:)
וַתֹּאמֶר אֶל עֲבָדֶיךָ הוֹרִדֻהוּ אֵלָי, וְאָשִׂימָה עֵינִי עָלָיו; וַנֹּאמֶר אֶל אֲדֹנִי לֹא יוּכַל הַנַּעַר לַעֲזֹב אֶת אָבִיו, וְעָזַב אֶת אָבִיו וָמֵת; וַתֹּאמֶר אֶל עֲבָדֶיךָ אִם לֹא יֵרֵד אֲחִיכֶם הַקָּטֹן אִתְּכֶם, לֹא תֹסִפוּן לִרְאוֹת פָּנָי; וַיְהִי כִּי עָלִינוּ אֶל עַבְדְּךָ אָבִי, וַנַּגֶּד לוֹ אֵת דִּבְרֵי אֲדֹנִי;
(:
שלישי
:)
וַיֹּאמֶר אָבִינוּ, שֻׁבוּ שִׁבְרוּ לָנוּ מְעַט אֹכֶל; וַנֹּאמֶר לֹא נוּכַל לָרֶדֶת, אִם יֵשׁ אָחִינוּ הַקָּטֹן אִתָּנוּ וְיָרַדְנוּ, כִּי לֹא נוּכַל לִרְאוֹת פְּנֵי הָאִישׁ וְאָחִינוּ הַקָּטֹן אֵינֶנּוּ אִתָּנוּ; וַיֹּאמֶר עַבְדְּךָ אָבִי אֵלֵינוּ, אַתֶּם יְדַעְתֶּם כִּי שְׁנַיִם יָלְדָה לִּי אִשְׁתִּי; וַיֵּצֵא הָאֶחָד מֵאִתִּי וָאֹמַר אַךְ טָרֹף טֹרָף, וְלֹא רְאִיתִיו עַד הֵנָּה; וּלְקַחְתֶּם גַּם אֶת זֶה מֵעִם פָּנַי וְקָרָהוּ אָסוֹן, וְהוֹרַדְתֶּם אֶת שֵׂיבָתִי בְּרָעָה שְׁאֹלָה; וְעַתָּה כְּבֹאִי אֶל עַבְדְּךָ אָבִי וְהַנַּעַר אֵינֶנּוּ אִתָּנוּ, וְנַפְשׁוֹ קְשׁוּרָה בְנַפְשׁוֹ;

specials/tora_teruma:
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִקְחוּ לִי תְּרוּמָה, מֵאֵת כּKל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ תִּקְחוּ אֶת תְּרוּמָתִי; וְזֹאת הַתְּרוּמָה אֲשֶׁר תִּקְחוּ מֵאִתָּם, זָהָב וָכֶסֶף וּנְחֹשֶׁת; וּתְכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי וְשֵׁשׁ וְעִזִּים; וְעֹרֹת אֵילִם מְאKדָּמִים וְעֹרֹת תְּחָשִׁים וַעֲצֵי שִׁטִּים;
(:
לוי
:)
שֶׁמֶן לַמָּאֹר, בְּשָׂמִים לְשֶׁמֶן הַמִּשְׁחָה וְלִקְטֹרֶת הַסַּמִּים; אַבְנֵי שֹׁהַם וְאַבְנֵי מִלֻּאִים, לָאֵפֹד וְלַחֹשֶׁן; וְעָשׂוּ לִי מִקְדָּשׁ, וְשָׁכַנְתִּי בְּתוֹכָם; כְּכֹל אֲשֶׁר אֲנִי מַרְאֶה אוֹתְךָ, אֵת תַּבְנִית הַמִּשְׁכָּן וְאֵת תַּבְנִית כּKל כֵּלָיו, וְכֵן תַּעֲשׂוּ;
(:
שלישי
:)
וְעָשׂוּ אֲרוֹן עֲצֵי שִׁטִּים, אַמָּתַיִם וָחֵצִי אKרְכּוֹ וְאַמָּה וָחֵצִי רKחְבּוֹ וְאַמָּה וָחֵצִי קֹמָתוֹ; וְצִפִּיתָ אֹתוֹ זָהָב טָהוֹר, מִבַּיִת וּמִחוּץ תְּצַפֶּנּוּ, וְעָשִׂיתָ עָלָיו זֵר זָהָב סָבִיב; וְיָצַקְתָּ לּוֹ אַרְבַּע טַבְּעֹת זָהָב, וְנָתַתָּה עַל אַרְבַּע פַּעֲמֹתָיו, וּשְׁתֵּי טַבָּעֹת עַל צַלְעוֹ הָאֶחָת וּשְׁתֵּי טַבָּעֹת עַל צַלְעוֹ הַשֵּׁנִית; וְעָשִׂיתָ בַדֵּי עֲצֵי שִׁטִּים, וְצִפִּיתָ אֹתָם זָהָב; וְהֵבֵאתָ אֶת הַבַּדִּים בַּטַּבָּעֹת, עַל צַלְעֹת הָאָרֹן לָשֵׂאת אֶת הָאָרֹן בָּהֶם; בְּטַבְּעֹת הָאָרֹן יִהְיוּ הַבַּדִּים, לֹא יָסֻרוּ מִמֶּנּוּ; וְנָתַתָּ אֶל הָאָרֹן, אֵת הָעֵדֻת אֲשֶׁר אֶתֵּן אֵלֶיךָ;

specials/tora_ree:
רְאֵה אָנֹכִי נֹתֵן לִפְנֵיכֶם הַיּוֹם, בְּרָכָה וּקְלָלָה; אֶת הַבְּרָכָה, אֲשֶׁר תִּשְׁמְעוּ אֶל מִצְוׂת י~הוה אֱ~לֹהֵיכֶם, אֲשֶׁר אָנֹכִי מְצַוֶּה אֶתְכֶם הַיּוֹם; וְהַקְּלָלָה אִם לֹא תִשְׁמְעוּ אֶל מִצְוׂת י~הוה אֱ~לֹהֵיכֶם, וְסַרְתֶּם מִן הַדֶּרֶךְ אֲשֶׁר אָנֹכִי מְצַוֶּה אֶתְכֶם הַיּוֹם, לָלֶכֶת אַחֲרֵי אֱלֹהִים אֲחֵרִים אֲשֶׁר לֹא יְדַעְתֶּם; וְהָיָה כִּי יְבִיאֲךָ י~הוה אֱ~לֹהֶיךָ אֶל הָאָרֶץ אֲשֶׁר אַתָּה בָא שָׁמָּה לְרִשְׁתָּהּ, וְנָתַתָּה אֶת הַבְּרָכָה עַל הַר גְּרִזִים וְאֶת הַקְּלָלָה עַל הַר עֵיבָל; הֲלֹא הֵמָּה בְּעֵבֶר הַיַּרְדֵּן, אַחֲרֵי דֶּרֶךְ מְבוֹא הַשֶּׁמֶשׁ, בְּאֶרֶץ הַכְּנַעֲנִי הַיֹּשֵׁב בָּעֲרָבָה, מוּל הַגִּלְגָּל אֵצֶל אֵלוֹנֵי מֹרֶה; כִּי אַתֶּם עֹבְרִים אֶת הַיַּרְדֵּן, לָבֹא לָרֶשֶׁת אֶת הָאָרֶץ אֲשֶׁר י~הוה אֱ~לֹהֵיכֶם נֹתֵן לָכֶם, וִירִשְׁתֶּם אֹתָהּ וִישַׁבְתֶּם בָּהּ;
(:
לוי
:)
וּשְׁמַרְתֶּם לַעֲשׂוֹת אֵת כּKל הַחֻקִּים וְאֶת הַמִּשְׁפָּטִים, אֲשֶׁר אָנֹכִי נֹתֵן לִפְנֵיכֶם הַיּוֹם; אֵלֶּה הַחֻקִּים וְהַמִּשְׁפָּטִים אֲשֶׁר תִּשְׁמְרוּן לַעֲשׂוֹת, בָּאָרֶץ אֲשֶׁר נָתַן י~הוה אֱ~לֹהֵי אֲבֹתֶיךָ לְךָ לְרִשְׁתָּהּ, כּKל הַיָּמִים אֲשֶׁר אַתֶּם חַיִּים עַל הָאֲדָמָה; אַבֵּד תְּאַבְּדוּן אֶת כּKל הַמְּקֹמוֹת אֲשֶׁר עָבְדוּ שָׁם הַגּוֹיִם אֲשֶׁר אַתֶּם יֹרְשִׁים אֹתָם אֶת אֱלֹהֵיהֶם, עַל הֶהָרִים הָרָמִים וְעַל הַגְּבָעוֹת וְתַחַת כּKל עֵץ רַעֲנָן; וְנִתַּצְתֶּם אֶת מִזְבּחֹתָם וְשִׁבַּרְתֶּם אֶת מַצֵּבֹתָם וַאֲשֵׁרֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ וּפְסִילֵי אֱלֹהֵיהֶם תְּגַדֵּעוּן, וְאִבַּדְתֶּם אֶת שְׁמָם מִן הַמָּקוֹם הַהוּא; לֹא תַעֲשׂוּן כֵּן לַי~הוה אֱ~לֹהֵיכֶם; כִּי אִם אֶל הַמָּקוֹם אֲשֶׁר יִבְחַר י~הוה אֱ~לֹהֵיכֶם מִכּKל שִׁבְטֵיכֶם לָשׂוּם אֶת שְׁמוֹ שָׁם, לְשִׁכְנוֹ תִדְרְשׁוּ וּבָאתָ שָּׁמָּה;
(:
שלישי
:)
וַהֲבֵאתֶם שָׁמָּה עֹלֹתֵיכֶם וְזִבְחֵיכֶם, וְאֵת מַעְשְׂרֹתֵיכֶם וְאֵת תְּרוּמַת יֶדְכֶם, וְנִדְרֵיכֶם וְנִדְבֹתֵיכֶם וּבְכֹרֹת בְּקַרְכֶם וְצֹאנְכֶם; וַאֲכַלְתֶּם שָׁם לִפְנֵי י~הוה אֱ~לֹהֵיכֶם, וּשְׂמַחְתֶּם בְּכֹל מִשְׁלַח יֶדְכֶם אַתֶּם וּבָתֵּיכֶם, אֲשֶׁר בֵּרַכְךָ י~הוה אֱ~לֹהֶיךָ; לֹא תַעֲשׂוּן כְּכֹל אֲשֶׁר אֲנַחְנוּ עֹשִׂים פֹּה הַיּוֹם, אִישׁ כּKל הַיָּשָׁר בְּעֵינָיו; כִּי לֹא בָּאתֶם עַד עָתָּה, אֶל הַמְּנוּחָה וְאֶל הַנַּחֲלָה אֲשֶׁר י~הוה אֱ~לֹהֶיךָ נֹתֵן לָךְ; וַעֲבַרְתֶּם אֶת הַיַּרְדֵּן, וִישַׁבְתֶּם בָּאָרֶץ אֲשֶׁר י~הוה אֱ~לֹהֵיכֶם  מַנְחִיל אֶתְכֶם, וְהֵנִיחַ לָכֶם מִכּKל אֹיְבֵיכֶם מִסָּבִיב וִישַׁבְתֶּם בֶּטַח;

specials/tora_pesach2:
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; קַדֶּשׁ לִי כKל בְּכוֹר, פֶּטֶר כּKל רֶחֶם בִּבְנֵי יִשְׂרָאֵל בָּאָדָם וּבַבְּהֵמָה, לִי הוּא; וַיֹּאמֶר מֹשֶׁה אֶל הָעָם, זָכוֹר אֶת הַיּוֹם הַזֶּה אֲשֶׁר יְצָאתֶם מִמִּצְרַיִם מִבֵּית עֲבָדִים, כִּי בְּחֹזֶק יָד הוֹצִיא י~הוה אֶתְכֶם מִזֶּה, וְלֹא יֵאָכֵל חָמֵץ; הַיּוֹם אַתֶּם יֹצְאִים, בְּחֹדֶשׁ הָאָבִיב;
(:
