וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה, אֵת יַעֲקֹב אִישׁ וּבֵיתוֹ בָּאוּ; רְאוּבֵן שִׁמְעוֹן לֵוִי וִיהוּדָה; יִשָּׂשכָר זְבוּלֻן וּבְנְיָמִן; דָּן וְנַפְתָּלִי גָּד וְאָשֵׁר; וַיְהִי כּKל נֶפֶשׁ יֹצְאֵי יֶרֶךְ יַעֲקֹב שִׁבְעִים נָפֶשׁ, וְיוֹסֵף הָיָה בְמִצְרָיִם; וַיָּמKת יוֹסֵף וְכKל אֶחָיו וְכֹל הַדּוֹר הַהוּא; וּבְנֵי יִשְׂרָאֵל פָּרוּ וַיִּשְׁרְצוּ וַיִּרְבּוּ וַיַּעַצְמוּ בִּמְאֹד מְאֹד, וַתִּמָּלֵא הָאָרֶץ אֹתָם;
(:
לוי
:)
וַיָּקKם מֶלֶךְ חָדָשׁ עַל מִצְרָיִם, אֲשֶׁר לֹא יָדַע אֶת יוֹסֵף; וַיֹּאמֶר אֶל עַמּוֹ, הִנֵּה עַם בְּנֵי יִשְׂרָאֵל רַב וְעָצוּם מִמֶּנּוּ; הָבָה נִתְחַכְּמָה לוֹ ,פֶּן יִרְבֶּה וְהָיָה כִּי תִקְרֶאנָה מִלְחָמָה וְנוֹסַף גַּם הוּא עַל שֹׂנְאֵינוּ, וְנִלְחַם בָּנוּ וְעָלָה מִן הָאָרֶץ; וַיָּשִׂימוּ עָלָיו שָׂרֵי מִסִּים לְמַעַן עַנֹּתוֹ בְּסִבְלֹתָם, וַיִּבֶן עָרֵי מִסְכְּנוֹת לְפַרְעֹה אֶת פִּתֹם וְאֶת רַעַמְסֵס; וְכַאֲשֶׁר יְעַנּוּ אֹתוֹ כֵּן יִרְבֶּה וְכֵן יִפְרֹץ, וַיָּקֻצוּ מִפְּנֵי בְּנֵי יִשְׂרָאֵל;
(:
שלישי
:)
וַיַּעֲבִדוּ מִצְרַיִם אֶת בְּנֵי יִשְׂרָאֵל בְּפָרֶךְ; וַיְמָרְרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה, בְּחֹמֶר וּבִלְבֵנִים וּבְכKל עֲבֹדָה בַּשָּׂדֶה, אֵת כּKל עֲבֹדָתָם אֲשֶׁר עָבְדוּ בָהֶם בְּפָרֶךְ; וַיֹּאמֶר מֶלֶךְ מִצְרַיִם לַמְיַלְּדֹת הָעִבְרִיֹּת, אֲשֶׁר שֵׁם הָאַחַת שִׁפְרָה וְשֵׁם הַשֵּׁנִית פּוּעָה; וַיֹּאמֶר בְּיַלֶּדְכֶן אֶת הָעִבְרִיּוֹת וּרְאִיתֶן עַל הָאKבְנָיִם, אִם בֵּן הוּא וַהֲמִתֶּן אֹתוֹ וְאִם בַּת הִיא וָחָיָה; וַתִּירֶאןָ הַמְיַלְּדֹת אֶת הָאֱ~לֹהִים וְלֹא עָשׂוּ כַּאֲשֶׁר דִּבֶּר אֲלֵיהֶן מֶלֶךְ מִצְרָיִם, וַתְּחַיֶּיןָ אֶת הַיְלָדִים;

specials/tora_haazinu:
הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה, וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי; יַעֲרֹף כַּמָּטָר לִקְחִי, תִּזַּל כַּטַּל אִמְרָתִי, כִּשְׂעִירִם עֲלֵי דֶשֶׁא וְכִרְבִיבִים עֲלֵי עֵשֶׂב; כִּי שֵׁם י~הוה אֶקְרָא, הָבוּ גֹדֶל לֵא~לֹהֵינוּ;
(:
לוי
:)
הַצּוּר תָּמִים פָּעֳלוֹ כִּי כKל דְּרָכָיו מִשְׁפָּט, אֵ~ל אֱמוּנָה וְאֵין עָוֶל, צַדִּיק וְיָשָׁר הוּא; שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם, דּוֹר עִקֵּשׁ וּפְתַלְתֹּל; הַ לְי~הוה תִּגְמְלוּ זֹאת, עַם נָבָל וְלֹא חָכָם, הֲלוֹא הוּא אָבִיךָ קָּנֶךָ, הוּא עָשְׂךָ וַיְכֹנְנֶךָ;
(:
שלישי
:)
זְכֹר יְמוֹת עוֹלָם, בִּינוּ שְׁנוֹת דּוֹר וָדוֹר, שְׁאַל אָבִיךָ וְיַגֵּדְךָ זְקֵנֶיךָ וְיֹאמְרוּ לָךְ; בְּהַנְחֵל עֶלְיוֹן גּוֹיִם, בְּהַפְרִידוֹ בְּנֵי אָדָם, יַצֵּב גְּבֻלֹת עַמִּים לְמִסְפַּר בְּנֵי יִשְׂרָאֵל; כִּי חֵלֶק י~הוה עַמּוֹ, יַעֲקֹב חֶבֶל נַחֲלָתוֹ; יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵל יְשִׁמֹן, יְסֹבְבֶנְהוּ יְבוֹנְנֵהוּ יִצְּרֶנְהוּ כְּאִישׁוֹן עֵינוֹ; כְּנֶשֶׁר יָעִיר קִנּוֹ עַל גּוֹזָלָיו יְרַחֵף, יִפְרֹשׂ כְּנָפָיו יִקָּחֵהוּ, יִשָּׂאֵהוּ עַל אֶבְרָתוֹ; י~הוה בָּדָד יַנְחֶנּוּ, וְאֵין עִמּוֹ אֵל נֵכָר;

specials/tora_vayeshev:
וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו, בְּאֶרֶץ כְּנָעַן; אֵלֶּה תֹּלְדוֹת יַעֲקֹב, יוֹסֵף בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה, הָיָה רֹעֶה אֶת אֶחָיו בַּצֹּאן, וְהוּא נַעַר אֶת בְּנֵי בִלְהָה וְאֶת בְּנֵי זִלְפָּה נְשֵׁי אָבִיו, וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה אֶל אֲבִיהֶם; וְיִשְׂרָאֵל אָהַב אֶת יוֹסֵף מִכּKל בָּנָיו, כִּי בֶן זְקֻנִים הוּא לוֹ, וְעָשָׂה לוֹ כְּתֹנֶת פַּסִּים;
(:
לוי
:)
וַיִּרְאוּ אֶחָיו כִּי אֹתוֹ אָהַב אֲבִיהֶם מִכּKל אֶחָיו, וַיִּשְׂנְאוּ אֹתוֹ, וְלֹא יָכְלוּ דַּבְּרוֹ לְשָׁלֹם; וַיַּחֲלֹם יוֹסֵף חֲלוֹם וַיַּגֵּד לְאֶחָיו, וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ; וַיֹּאמֶר אֲלֵיהֶם שִׁמְעוּ נָא הַחֲלוֹם הַזֶּה אֲשֶׁר חָלָמְתִּי; וְהִנֵּה אֲנַחְנוּ מְאַלְּמִים אֲלֻמִּים בְּתוֹךְ הַשָּׂדֶה, וְהִנֵּה קָמָה אֲלֻמָּתִי וְגַם נִצָּבָה, וְהִנֵּה תְסֻבֶּינָה אֲלֻמֹּתֵיכֶם וַתִּשְׁתַּחֲוֶיןָ לַאֲלֻמָּתִי;
(:
שלישי
:)
וַיֹּאמְרוּ לוֹ אֶחָיו, הֲמָלֹךְ תִּמְלֹךְ עָלֵינוּ, אִם מָשׁוֹל תִּמְשֹׁל בָּנוּ, וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ עַל חֲלֹמֹתָיו וְעַל דְּבָרָיו; וַיַּחֲלֹם עוֹד חֲלוֹם אַחֵר וַיְסַפֵּר אֹתוֹ לְאֶחָיו, וַיֹּאמֶר הִנֵּה חָלַמְתִּי חֲלוֹם עוֹד וְהִנֵּה הַשֶּׁמֶשׁ וְהַיָּרֵחַ וְאַחַד עָשָׂר כּוֹכָבִים מִשְׁתַּחֲוִים לִי; וַיְסַפֵּר אֶל אָבִיו וְאֶל אֶחָיו, וַיִּגְעַר בּוֹ אָבִיו וַיֹּאמֶר לוֹ מָה הַחֲלוֹם הַזֶּה אֲשֶׁר חָלָמְתָּ, הֲבוֹא נָבוֹא אֲנִי וְאִמְּךָ וְאַחֶיךָ לְהִשְׁתַּחֲוׂת לְךָ אָרְצָה; וַיְקַנְאוּ בוֹ אֶחָיו וְאָבִיו שָׁמַר אֶת הַדָּבָר;

specials/tora_bemidbar:
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה בְּמִדְבַּר סִינַי בְּאֹהֶל מוֹעֵד, בְּאֶחָד לַחֹדֶשׁ הַשֵּׁנִי בַּשָּׁנָה הַשֵּׁנִית לְצֵאתָם מֵאֶרֶץ מִצְרַיִם לֵאמֹר; שְׂאוּ אֶת רֹאשׁ כּKל עֲדַת בְּנֵי יִשְׂרָאֵל לְמִשְׁפְּחֹתָם לְבֵית אֲבֹתָם, בְּמִסְפַּר שֵׁמוֹת כּKל זָכָר לְגֻלְגְּלֹתָם; מִבֶּן עֶשְׂרִים שָׁנָה וָמַעְלָה כּKל יֹצֵא צָבָא בְּיִשְׂרָאֵל, תִּפְקְדוּ אֹתָם לְצִבְאֹתָם אַתָּה וְאַהֲרֹן; וְאִתְּכֶם יִהְיוּ אִישׁ אִישׁ לַמַּטֶּה, אִישׁ רֹאשׁ לְבֵית אֲבֹתָיו הוּא;
(:
לוי
:)
וְאֵלֶּה שְׁמוֹת הָאֲנָשִׁים אֲשֶׁר יַעַמְדוּ אִתְּכֶם, לִרְאוּבֵן אֱלִיצוּר בֶּן שְׁדֵיאוּר; לְשִׁמְעוֹן שְׁלֻמִיאֵל בֶּן צוּרִישַׁדָּי; לִיהוּדָה נַחְשׁוֹן בֶּן עַמִּינָדָב; לְיִשָּׂשכָר נְתַנְאֵל בֶּן צוּעָר; לִזְבוּלֻן אֱלִיאָב בֶּן חֵלֹן; לִבְנֵי יוֹסֵף לְאֶפְרַיִם אֱלִישָׁמָע בֶּן עַמִּיהוּד, לִמְנַשֶּׁה גַּמְלִיאֵל בֶּן פְּדָהצוּר; לְבִנְיָמִן אֲבִידָן בֶּן גִּדְעֹנִי; לְדָן אֲחִיעֶזֶר בֶּן עַמִּישַׁדָּי; לְאָשֵׁר פַּגְעִיאֵל בֶּן עKכְרָן; לְגָד אֶלְיָסָף בֶּן דְּעוּאֵל; לְנַפְתָּלִי אֲחִירַע בֶּן עֵינָן; אֵלֶּה קְרוּאֵי הָעֵדָה נְשִׂיאֵי מַטּוֹת אֲבוֹתָם, רָאשֵׁי אַלְפֵי יִשְׂרָאֵל הֵם;
(:
שלישי
:)
וַיִּקַּח מֹשֶׁה וְאַהֲרֹן, אֵת הָאֲנָשִׁים הָאֵלֶּה אֲשֶׁר נִקְּבוּ בְּשֵׁמוֹת; וְאֵת כּKל הָעֵדָה הִקְהִילוּ בְּאֶחָד לַחֹדֶשׁ הַשֵּׁנִי, וַיִּתְיַלְדוּ עַל מִשְׁפְּחֹתָם לְבֵית אֲבֹתָם, בְּמִסְפַּר שֵׁמוֹת מִבֶּן עֶשְׂרִים שָׁנָה וָמַעְלָה לְגֻלְגְּלֹתָם; כַּאֲשֶׁר צִוָּה י~הוה אֶת מֹשֶׁה, וַיִּפְקְדֵם בְּמִדְבַּר סִינָי;

specials/tora_kedoshim:
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; דַּבֵּר אֶל כּKל עֲדַת בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם קְדֹשִׁים תִּהְיוּ, כִּי קָדוֹשׁ אֲנִי י~הוה אֱ~לֹהֵיכֶם; אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְאֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ, אֲנִי י~הוה אֱ~לֹהֵיכֶם; אַל תִּפְנוּ אֶל הָאֱלִילִים וֵאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם, אֲנִי י~הוה אֱ~לֹהֵיכֶם;
(:
לוי
:)
וְכִי תִזְבְּחוּ זֶבַח שְׁלָמִים לַי~הוה, לִרְצֹנְכֶם תִּזְבָּחֻהוּ; בְּיוֹם זִבְחֲכֶם יֵאָכֵל וּמִמָּחֳרָת, וְהַנּוֹתָר עַד יוֹם הַשְּׁלִישִׁי בָּאֵשׁ יִשָּׂרֵף; וְאִם הֵאָכֹל יֵאָכֵל בַּיּוֹם הַשְּׁלִישִׁי, פִּגּוּל הוּא לֹא יֵרָצֶה; וְאֹכְלָיו עֲוׂנוֹ יִשָּׂא, כִּי אֶת קֹדֶשׁ י~הוה חִלֵּל, וְנִכְרְתָה הַנֶּפֶשׁ הַהִוא מֵעַמֶּיהָ; וּבְקֻצְרְכֶם אֶת קְצִיר אַרְצְכֶם לֹא תְכַלֶּה פְּאַת שָׂדְךָ לִקְצֹר, וְלֶקֶט קְצִירְךָ לֹא תְלַקֵּט; וְכַרְמְךָ לֹא תְעוֹלֵל וּפֶרֶט כַּרְמְךָ לֹא תְלַקֵּט, לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם אֲנִי י~הוה אֱ~לֹהֵיכֶם;
(:
שלישי
:)
לֹא תִּגְנֹבוּ, וְלֹא תְכַחֲשׁוּ וְלֹא תְשַׁקְּרוּ אִישׁ בַּעֲמִיתוֹ; וְלֹא תִשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר, וְחִלַּלְתָּ אֶת שֵׁם אֱ~לֹהֶיךָ אֲנִי י~הוה; לֹא תַעֲשֹׁק אֶת רֵעֲךָ וְלֹא תִגְזֹל, לֹא תָלִין פְּעֻלַּת שָׂכִיר אִתְּךָ עַד בֹּקֶר; לֹא תְקַלֵּל חֵרֵשׁ וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשֹׁל, וְיָרֵאתָ מֵּאֱ~לֹהֶיךָ אֲנִי י~הוה;

specials/tora_yitro:
וַיִּשְׁמַע יִתְרוֹ כֹהֵן מִדְיָן חֹתֵן מֹשֶׁה אֵת כּKל אֲשֶׁר עָשָׂה אֱ~לֹהִים לְמֹשֶׁה וּלְיִשְׂרָאֵל עַמּוֹ, כִּי הוֹצִיא י~הוה אֶת יִשְׂרָאֵל מִמִּצְרָיִם; וַיִּקַּח יִתְרוֹ חֹתֵן מֹשֶׁה אֶת צִפֹּרָה אֵשֶׁת מֹשֶׁה, אַחַר שִׁלּוּחֶיהָ; וְאֵת שְׁנֵי בָנֶיהָ, אֲשֶׁר שֵׁם הָאֶחָד גֵּרְשֹׁם כִּי אָמַר גֵּר הָיִיתִי בְּאֶרֶץ נָכְרִיָּה; וְשֵׁם הָאֶחָד אֱלִיעֶזֶר, כִּי אֱ~לֹהֵי אָבִי בְּעֶזְרִי וַיַּצִּלֵנִי מֵחֶרֶב פַּרְעֹה;
(:
לוי
:)
וַיָּבֹא יִתְרוֹ חֹתֵן מֹשֶׁה וּבָנָיו וְאִשְׁתּוֹ אֶל מֹשֶׁה, אֶל הַמִּדְבָּר אֲשֶׁר הוּא חֹנֶה שָׁם הַר הָאֱ~לֹהִים; וַיֹּאמֶר אֶל מֹשֶׁה אֲנִי חֹתֶנְךָ יִתְרוֹ בָּא אֵלֶיךָ, וְאִשְׁתְּךָ וּשְׁנֵי בָנֶיהָ עִמָּהּ; וַיֵּצֵא מֹשֶׁה לִקְרַאת חֹתְנוֹ וַיִּשְׁתַּחוּ וַיִּשַּׁק לוֹ וַיִּשְׁאֲלוּ אִישׁ לְרֵעֵהוּ לְשָׁלוֹם, וַיָּבֹאוּ הָאֹהֱלָה; וַיְסַפֵּר מֹשֶׁה לְחֹתְנוֹ אֵת כּKל אֲשֶׁר עָשָׂה י~הוה לְפַרְעֹה וּלְמִצְרַיִם עַל אוֹדֹת יִשְׂרָאֵל, אֵת כּKל הַתְּלָאָה אֲשֶׁר מְצָאָתַם בַּדֶּרֶךְ וַיַּצִּלֵם י~הוה;
(:
שלישי
:)
וַיִּחַדְּ יִתְרוֹ עַל כּKל הַטּוֹבָה אֲשֶׁר עָשָׂה י~הוה לְיִשְׂרָאֵל, אֲשֶׁר הִצִּילוֹ מִיַּד מִצְרָיִם; וַיֹּאמֶר יִתְרוֹ בָּרוּךְ י~הוה אֲשֶׁר הִצִּיל אֶתְכֶם מִיַּד מִצְרַיִם וּמִיַּד פַּרְעֹה, אֲשֶׁר הִצִּיל אֶת הָעָם מִתַּחַת יַד מִצְרָיִם; עַתָּה יָדַעְתִּי כִּי גָדוֹל י~הוה מִכָּל הָאֱ~לֹהִים, כִּי בַדָּבָר אֲשֶׁר זָדוּ עֲלֵיהֶם; וַיִּקַּח יִתְרוֹ חֹתֵן מֹשֶׁה עֹלָה וּזְבָחִים לֵא~לֹהִים, וַיָּבֹא אַהֲרֹן וְכֹל זִקְנֵי יִשְׂרָאֵל לֶאֱכKל לֶחֶם עִם חֹתֵן מֹשֶׁה לִפְנֵי הָאֱ~לֹהִים;

specials/tora_vezot_haberacha:
וְזֹאת הַבְּרָכָה אֲשֶׁר בֵּרַךְ מֹשֶׁה אִישׁ הָאֱ~לֹהִים אֶת בְּנֵי יִשְׂרָאֵל, לִפְנֵי מוֹתוֹ; וַיֹּאמַר, י~הוה מִסִּינַי בָּא וְזָרַח מִשֵּׂעִיר לָמוֹ, הוֹפִיעַ מֵהַר פָּארָן וְאָתָה מֵרִבְבֹת קֹדֶשׁ, מִימִינוֹ אֵשׁ דָּת לָמוֹ; אַף חֹבֵב עַמִּים כּKל קְדֹשָׁיו בְּיָדֶךָ, וְהֵם תֻּכּוּ לְרַגְלֶךָ יִשָּׂא מִדַּבְּרֹתֶיךָ; תּוֹרָה צִוָּה לָנוּ מֹשֶׁה, מוֹרָשָׁה קְהִלַּת יַעֲקֹב; וַיְהִי בִישֻׁרוּן מֶלֶךְ, בְּהִתְאַסֵּף רָאשֵׁי עָם יַחַד שִׁבְטֵי יִשְׂרָאֵל; יְחִי רְאוּבֵן וְאַל יָמֹת, וִיהִי מְתָיו מִסְפָּר; וְזֹאת לִיהוּדָה וַיֹּאמַר, שְׁמַע י~הוה קוֹל יְהוּדָה וְאֶל עַמּוֹ תְּבִיאֶנּוּ, יָדָיו רָב לוֹ וְעֵזֶר מִצָּרָיו תִּהְיֶה;
(:
לוי
:)
וּלְלֵוִי אָמַר תֻּמֶּיךָ וְאוּרֶיךָ לְאִישׁ חֲסִידֶךָ, אֲשֶׁר נִסִּיתוֹ בְּמַסָּה, תְּרִיבֵהוּ עַל מֵי מְרִיבָה; הָאֹמֵר לְאָבִיו וּלְאִמּוֹ לֹא רְאִיתִיו וְאֶת אֶחָיו לֹא הִכִּיר וְאֶת בָּנָיו לֹא יָדָע, כִּי שָׁמְרוּ אִמְרָתֶךָ וּבְרִיתְךָ יִנְצֹרוּ; יוֹרוּ מִשְׁפָּטֶיךָ לְיַעֲקֹב וְתוֹרָתְךָ לְיִשְׂרָאֵל, יָשִׂימוּ קְטוֹרָה בְּאַפֶּךָ וְכָלִיל עַל מִזְבְּחֶךָ; בָּרֵךְ י~הוה חֵילוֹ וּפֹעַל יָדָיו תִּרְצֶה, מְחַץ מKתְנַיִם קָמָיו וּמְשַׂנְאָיו מִן יְקוּמוּן; לְבִנְיָמִן אָמַר יְדִיד י~הוה יִשְׁכֹּן לָבֶטַח עָלָיו, חֹפֵף עָלָיו כּKל הַיּוֹם וּבֵין כְּתֵפָיו שָׁכֵן;
(:
שלישי
:)
וּלְיוֹסֵף אָמַר מְבֹרֶכֶת י~הוה אַרְצוֹ, מִמֶּגֶד שָׁמַיִם מִטָּל וּמִתְּהוֹם רֹבֶצֶת תָּחַת; וּמִמֶּגֶד תְּבוּאֹת שָׁמֶשׁ, וּמִמֶּגֶד גֶּרֶשׁ יְרָחִים; וּמֵרֹאשׁ הַרְרֵי קֶדֶם, וּמִמֶּגֶד גִּבְעוֹת עוֹלָם; וּמִמֶּגֶד אֶרֶץ וּמְלֹאָהּ וּרְצוֹן שֹׁכְנִי סְנֶה, תָּבוֹאתָה לְרֹאשׁ יוֹסֵף וּלְקKדְקֹד נְזִיר אֶחָיו; בְּכוֹר שׁוֹרוֹ הָדָר לוֹ וְקַרְנֵי רְאֵם קַרְנָיו, בָּהֶם עַמִּים יְנַגַּח יַחְדָּו אַפְסֵי אָרֶץ, וְהֵם רִבְבוֹת אֶפְרַיִם וְהֵם אַלְפֵי מְנַשֶּׁה;

specials/tora_behaalotecha:
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; דַּבֵּר אֶל אַהֲרֹן וְאָמַרְתָּ אֵלָיו, בְּהַעֲלֹתְךָ אֶת הַנֵּרֹת אֶל מוּל פְּנֵי הַמְּנוֹרָה יָאִירוּ שִׁבְעַת הַנֵּרוֹת; וַיַּעַשׂ כֵּן אַהֲרֹן, אֶל מוּל פְּנֵי הַמְּנוֹרָה הֶעֱלָה נֵרֹתֶיהָ, כַּאֲשֶׁר צִוָּה י~הוה אֶת מֹשֶׁה; וְזֶה מַעֲשֵׂה הַמְּנֹרָה מִקְשָׁה זָהָב, עַד יְרֵכָהּ עַד פִּרְחָהּ מִקְשָׁה הִוא, כַּמַּרְאֶה אֲשֶׁר הֶרְאָה י~הוה אֶת מֹשֶׁה כֵּן עָשָׂה אֶת הַמְּנֹרָה;
(:
לוי
:)
וַיְדַבֵּר י~הוה אֶל מֹשֶׁה לֵּאמֹר; קַח אֶת הַלְוִיִּם מִתּוֹךְ בְּנֵי יִשְׂרָאֵל, וְטִהַרְתָּ אֹתָם; וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם, הַזֵּה עֲלֵיהֶם מֵי חַטָּאת, וְהֶעֱבִירוּ תַעַר עַל כּKל בְּשָׂרָם וְכִבְּסוּ בִגְדֵיהֶם וְהִטֶּהָרוּ; וְלָקְחוּ פַּר בֶּן בָּקָר וּמִנְחָתוֹ סֹלֶת בְּלוּלָה בַשָּׁמֶן, וּפַר שֵׁנִי בֶן בָּקָר תִּקַּח לְחַטָּאת; וְהִקְרַבְתָּ אֶת הַלְוִיִּם לִפְנֵי אֹהֶל מוֹעֵד, וְהִקְהַלְתָּ אֶת כּKל עֲדַת בְּנֵי יִשְׂרָאֵל;
(:
שלישי
:)
וְהִקְרַבְתָּ אֶת הַלְוִיִּם לִפְנֵי י~הוה, וְסָמְכוּ בְנֵי יִשְׂרָאֵל אֶת יְדֵיהֶם עַל הַלְוִיִּם; וְהֵנִיף אַהֲרֹן אֶת הַלְוִיִּם תְּנוּפָה לִפְנֵי י~הוה מֵאֵת בְּנֵי יִשְׂרָאֵל, וְהָיוּ לַעֲבֹד אֶת עֲבֹדַת י~הוה; וְהַלְוִיִּם יִסְמְכוּ אֶת יְדֵיהֶם עַל רֹאשׁ הַפָּרִים, וַעֲשֵׂה אֶת הָאֶחָד חַטָּאת וְאֶת הָאֶחָד עֹלָה לַי~הוה, לְכַפֵּר עַל הַלְוִיִּם; וְהַעֲמַדְתָּ אֶת הַלְוִיִּם לִפְנֵי אַהֲרֹן וְלִפְנֵי בָנָיו, וְהֵנַפְתָּ אֹתָם תְּנוּפָה לַי~הוה; וְהִבְדַּלְתָּ אֶת הַלְוִיִּם מִתּוֹךְ בְּנֵי יִשְׂרָאֵל, וְהָיוּ לִי הַלְוִיִּם;

specials/tora_shemini:
וַיְהִי בַּיּוֹם הַשְּׁמִינִי, קָרָא מֹשֶׁה לְאַהֲרֹן וּלְבָנָיו, וּלְזִקְנֵי יִשְׂרָאֵל; וַיֹּאמֶר אֶל אַהֲרֹן קַח לְךָ עֵגֶל בֶּן בָּקָר לְחַטָּאת וְאַיִל לְעֹלָה תְּמִימִם, וְהַקְרֵב לִפְנֵי י~הוה; וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר, קְחוּ שְׂעִיר עִזִּים לְחַטָּאת וְעֵגֶל וָכֶבֶשׂ בְּנֵי שָׁנָה תְּמִימִם לְעֹלָה; וְשׁוֹר וָאַיִל לִשְׁלָמִים לִזְבֹּחַ לִפְנֵי י~הוה וּמִנְחָה בְּלוּלָה בַשָּׁמֶן, כִּי הַיּוֹם י~הוה נִרְאָה אֲלֵיכֶם; וַיִּקְחוּ אֵת אֲשֶׁר צִוָּה מֹשֶׁה אֶל פְּנֵי אֹהֶל מוֹעֵד, וַיִּקְרְבוּ כּKל הָעֵדָה וַיַּעַמְדוּ לִפְנֵי י~הוה; וַיֹּאמֶר מֹשֶׁה זֶה הַדָּבָר אֲשֶׁר צִוָּה י~הוה תַּעֲשׂוּ, וְיֵרָא אֲלֵיכֶם כְּבוֹד י~הוה;
(:
