וַיְדַבֵּר י~הוה אֶל מֹשֶׁה וְאֶל אַהֲרֹן לֵאמֹר; אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ שְׂאֵת אוֹ סַפַּחַת אוֹ בַהֶרֶת, וְהָיָה בְעוֹר בְּשָׂרוֹ לְנֶגַע צָרָעַת, וְהוּבָא אֶל אַהֲרֹן הַכֹּהֵן אוֹ אֶל אַחַד מִבָּנָיו הַכֹּהֲנִים; וְרָאָה הַכֹּהֵן אֶת הַנֶּגַע בְּעוֹר הַבָּשָׂר וְשֵׂעָר בַּנֶּגַע הָפַךְ לָבָן וּמַרְאֵה הַנֶּגַע עָמֹק מֵעוֹר בְּשָׂרוֹ, נֶגַע צָרַעַת הוּא, וְרָאָהוּ הַכֹּהֵן וְטִמֵּא אֹתוֹ; וְאִם בַּהֶרֶת לְבָנָה הִוא בְּעוֹר בְּשָׂרוֹ וְעָמֹק אֵין מַרְאֶהָ מִן הָעוֹר וּשְׂעָרָה לֹא הָפַךְ לָבָן, וְהִסְגִּיר הַכֹּהֵן אֶת הַנֶּגַע שִׁבְעַת יָמִים; וְרָאָהוּ הַכֹּהֵן בַּיּוֹם הַשְּׁבִיעִי, וְהִנֵּה הַנֶּגַע עָמַד בְּעֵינָיו, לֹא פָשָׂה הַנֶּגַע בָּעוֹר, וְהִסְגִּירוֹ הַכֹּהֵן שִׁבְעַת יָמִים שֵׁנִית;

specials/tora_vayera:
וַיֵּרָא אֵלָיו י~הוה בְּאֵלֹנֵי מַמְרֵא, וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל כְּחֹם הַיּוֹם; וַיִּשָּׂא עֵינָיו וַיַּרְא, וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים נִצָּבִים עָלָיו, וַיַּרְא וַיָּרKץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל וַיִּשְׁתַּחוּ אָרְצָה; וַיֹּאמַר, אֲ~דֹנָי אִם נָא מָצָאתִי חֵן בְּעֵינֶיךָ אַל נָא תַעֲבֹר מֵעַל עַבְדֶּךָ; יֻקַּח נָא מְעַט מַיִם וְרַחֲצוּ רַגְלֵיכֶם, וְהִשָּׁעֲנוּ תַּחַת הָעֵץ; וְאֶקְחָה פַת לֶחֶם וְסַעֲדוּ לִבְּכֶם אַחַר תַּעֲבֹרוּ, כִּי עַל כֵּן עֲבַרְתֶּם עַל עַבְדְּכֶם, וַיֹּאמְרוּ כֵּן תַּעֲשֶׂה כַּאֲשֶׁר דִּבַּרְתָּ;
(:
לוי
:)
וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל שָׂרָה, וַיֹּאמֶר מַהֲרִי שְׁלֹשׁ סְאִים קֶמַח סֹלֶת, לוּשִׁי וַעֲשִׂי עֻגוֹת; וְאֶל הַבָּקָר רָץ אַבְרָהָם, וַיִּקַּח בֶּן בָּקָר רַךְ וָטוֹב וַיִּתֵּן אֶל הַנַּעַר וַיְמַהֵר לַעֲשׂוֹת אֹתוֹ; וַיִּקַּח חֶמְאָה וְחָלָב, וּבֶן הַבָּקָר אֲשֶׁר עָשָׂה, וַיִּתֵּן לִפְנֵיהֶם, וְהוּא עֹמֵד עֲלֵיהֶם תַּחַת הָעֵץ וַיֹּאכֵלוּ;
(:
שלישי
:)
וַיֹּאמְרוּ אֵלָיו אַיֵּה שָׂרָה אִשְׁתֶּךָ, וַיֹּאמֶר הִנֵּה בָאֹהֶל; וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה, וְהִנֵּה בֵן לְשָׂרָה אִשְׁתֶּךָ, וְשָׂרָה שֹׁמַעַת פֶּתַח הָאֹהֶל וְהוּא אַחֲרָיו; וְאַבְרָהָם וְשָׂרָה זְקֵנִים בָּאִים בַּיָּמִים, חָדַל לִהְיוֹת לְשָׂרָה אֹרַח כַּנָּשִׁים; וַתִּצְחַק שָׂרָה בְּקִרְבָּהּ לֵאמֹר, אַחֲרֵי בְלֹתִי הָיְתָה לִּי עֶדְנָה וַאדֹנִי זָקֵן; וַיֹּאמֶר י~הוה אֶל אַבְרָהָם, לָמָּה זֶּה צָחֲקָה שָׂרָה לֵאמֹר הַאַף אֻמְנָם אֵלֵד וַאֲנִי זָקַנְתִּי; הֲיִפָּלֵא מֵי~הוה דָּבָר, לַמּוֹעֵד אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה וּלְשָׂרָה בֵן;

specials/tora_korach:
וַיִּקַּח קֹרַח בֶּן יִצְהָר בֶּן קְהָת בֶּן לֵוִי, וְדָתָן וַאֲבִירָם בְּנֵי אֱלִיאָב, וְאוֹן בֶּן פֶּלֶת, בְּנֵי רְאוּבֵן; וַיָּקֻמוּ לִפְנֵי מֹשֶׁה וַאֲנָשִׁים מִבְּנֵי יִשְׂרָאֵל חֲמִשִּׁים וּמָאתָיִם, נְשִׂיאֵי עֵדָה קְרִאֵי מוֹעֵד אַנְשֵׁי שֵׁם; וַיִּקָּהֲלוּ עַל מֹשֶׁה וְעַל אַהֲרֹן וַיֹּאמְרוּ אֲלֵהֶם רַב לָכֶם, כִּי כKל הָעֵדָה כֻּלָּם קְדֹשִׁים וּבְתוֹכָם י~הוה, וּמַדּוּעַ תִּתְנַשְּׂאוּ עַל קְהַל י~הוה;
(:
לוי
:)
וַיִּשְׁמַע מֹשֶׁה וַיִּפֹּל עַל פָּנָיו; וַיְדַבֵּר אֶל קֹרַח וְאֶל כּKל עֲדָתוֹ לֵאמֹר, בֹּקֶר וְיֹדַע י~הוה אֶת אֲשֶׁר לוֹ וְאֶת הַקָּדוֹשׁ וְהִקְרִיב אֵלָיו, וְאֵת אֲשֶׁר יִבְחַר בּוֹ יַקְרִיב אֵלָיו; זֹאת עֲשׂוּ, קְחוּ לָכֶם מַחְתּוֹת קֹרַח וְכKל עֲדָתוֹ; וּתְנוּ בָהֵן אֵשׁ וְשִׂימוּ עֲלֵיהֶן קְטֹרֶת לִפְנֵי י~הוה מָחָר, וְהָיָה הָאִישׁ אֲשֶׁר יִבְחַר י~הוה הוּא הַקָּדוֹשׁ, רַב לָכֶם בְּנֵי לֵוִי;
(:
שלישי
:)
וַיֹּאמֶר מֹשֶׁה אֶל קֹרַח, שִׁמְעוּ נָא בְּנֵי לֵוִי; הַמְעַט מִכֶּם כִּי הִבְדִּיל אֱ~לֹהֵי יִשְׂרָאֵל אֶתְכֶם מֵעֲדַת יִשְׂרָאֵל לְהַקְרִיב אֶתְכֶם אֵלָיו, לַעֲבֹד אֶת עֲבֹדַת מִשְׁכַּן י~הוה וְלַעֲמֹד לִפְנֵי הָעֵדָה לְשָׁרְתָם; וַיַּקְרֵב אֹתְךָ וְאֶת כּKל אַחֶיךָ בְנֵי לֵוִי אִתָּךְ, וּבִקַּשְׁתֶּם גַּם כְּהֻנָּה; לָכֵן אַתָּה וְכKל עֲדָתְךָ הַנֹּעָדִים עַל י~הוה, וְאַהֲרֹן מַה הוּא כִּי תַלִּינוּ עָלָיו; וַיִּשְׁלַח מֹשֶׁה לִקְרֹא לְדָתָן וְלַאֲבִירָם בְּנֵי אֱלִיאָב, וַיֹּאמְרוּ לֹא נַעֲלֶה; הַמְעַט כִּי הֶעֱלִיתָנוּ מֵאֶרֶץ זָבַת חָלָב וּדְבַשׁ לַהֲמִיתֵנוּ בַּמִּדְבָּר, כִּי תִשְׂתָּרֵר עָלֵינוּ גַּם הִשְׂתָּרֵר;

specials/tora_nitzavim:
אַתֶּם נִצָּבִים הַיּוֹם כֻּלְּכֶם לִפְנֵי י~הוה אֱ~לֹהֵיכֶם, רָאשֵׁיכֶם שִׁבְטֵיכֶם זִקְנֵיכֶם וְשֹׁטְרֵיכֶם, כֹּל אִישׁ יִשְׂרָאֵל; טַפְּכֶם נְשֵׁיכֶם וְגֵרְךָ אֲשֶׁר בְּקֶרֶב מַחֲנֶיךָ, מֵחֹטֵב עֵצֶיךָ עַד שֹׁאֵב מֵימֶיךָ; לְעKבְרְךָ בִּבְרִית י~הוה אֱ~לֹהֶיךָ וּבְאָלָתוֹ, אֲשֶׁר י~הוה אֱ~לֹהֶיךָ כֹּרֵת עִמְּךָ הַיּוֹם;
(:
לוי
:)
לְמַעַן הָקִים אֹתְךָ הַיּוֹם לוֹ לְעָם וְהוּא יִהְיֶה לְּךָ לֵא~לֹהִים כַּאֲשֶׁר דִּבֶּר לָךְ, וְכַאֲשֶׁר נִשְׁבַּע לַאֲבֹתֶיךָ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב; וְלֹא אִתְּכֶם לְבַדְּכֶם, אָנֹכִי כֹּרֵת אֶת הַבְּרִית הַזֹּאת וְאֶת הָאָלָה הַזֹּאת; כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה עִמָּנוּ עֹמֵד הַיּוֹם לִפְנֵי י~הוה אֱ~לֹהֵינוּ, וְאֵת אֲשֶׁר אֵינֶנּוּ פֹּה עִמָּנוּ הַיּוֹם;
(:
